window.QB_TKP_B26 = [
{"id":"TKP-5051", "q":"Seorang deportan yang baru dipulangkan dari zona konflik luar negeri melamar menjadi tenaga honorer di instansi Anda dengan dokumen lengkap. Ia mengaku sudah bebas dari paham ekstrem yang dulu dianutnya. Sikap Anda sebagai panitia rekrutmen?", "opts":[{"t":"Menerima berkasnya sesuai prosedur, namun melaporkan status deportannya ke pimpinan dan BNPT untuk pembinaan dan pemantauan lanjutan.","s":5},{"t":"Menerima berkasnya sesuai prosedur dan meminta ia menandatangani pernyataan setia pada Pancasila dan NKRI.","s":4},{"t":"Menerima berkasnya seperti pelamar lain tanpa perlakuan khusus selama dokumennya lengkap.","s":3},{"t":"Menolak diam-diam berkasnya tanpa alasan jelas agar tidak menimbulkan masalah.","s":2},{"t":"Menyebarkan status deportannya ke media sosial agar masyarakat waspada.","s":1}], "ex":"Deportan berhak direkrut secara adil, tetapi statusnya wajib dilaporkan ke pimpinan dan aparat agar pembinaan serta pemantauan berjalan; penolakan diam-diam atau penyebaran data pribadi melanggar hukum."},
{"id":"TKP-5052", "q":"Di lingkungan RT Anda, seorang deportan eks simpatisan jaringan teroris membuka warung dan bersikap ramah. Sebagian warga mengusulkan mengusirnya karena khawatir paham ekstremnya menular. Sebagai ASN yang tinggal di sana, sikap Anda?", "opts":[{"t":"Menolak usulan pengusiran, mengajak warga menerima dengan syarat ia ikut program deradikalisasi dan dilaporkan ke RT/RW serta aparat setempat.","s":5},{"t":"Menolak usulan pengusiran dan mengajak warga memberinya kesempatan berbaur secara wajar.","s":4},{"t":"Tidak ikut campur karena itu urusan warga setempat.","s":3},{"t":"Setuju diusir saja demi keamanan lingkungan.","s":2},{"t":"Ikut menyebarkan isu bahwa ia masih menyimpan paham ekstrem tanpa bukti.","s":1}], "ex":"Mantan simpatisan yang sudah menjalani proses hukum berhak reintegrasi; pengusiran tanpa dasar melanggar HAM, sedangkan penerimaan harus disertai pembinaan dan koordinasi dengan aparat."},
{"id":"TKP-5053", "q":"Rekan kerja Anda menerima kiriman paket dari kerabatnya yang dideportasi dari luar negeri karena terlibat jaringan ekstrem. Paket itu berisi buku-buku berideologi radikal. Sikap Anda?", "opts":[{"t":"Menasihati rekan agar menyerahkan buku-buku itu ke aparat dan melaporkan kiriman tersebut melalui jalur resmi.","s":5},{"t":"Menasihati rekan agar memusnahkan buku-buku itu dan memutus kontak dengan pengirimnya.","s":4},{"t":"Membiarkannya karena itu urusan pribadi rekan dan keluarganya.","s":3},{"t":"Ikut membaca bukunya karena penasaran dengan isinya.","s":2},{"t":"Meminta salinan bukunya untuk disebar ke teman-teman lain.","s":1}], "ex":"Materi propaganda ekstrem dari jaringan luar negeri harus diserahkan ke aparat, bukan dibaca atau disebar; pembiaran membuka celah penyebaran paham radikal."},
{"id":"TKP-5054", "q":"Anak tetangga Anda yang baru dideportasi dari luar negeri bercerita di warung bahwa ia pernah dilatih kelompok teroris dan kini ingin hidup normal. Beberapa warga ingin melaporkannya agar ditangkap lagi. Sikap Anda?", "opts":[{"t":"Menjelaskan ke warga bahwa ia sudah menjalani proses hukum, lalu mengarahkan agar pembinaannya dikoordinasikan dengan aparat dan tokoh masyarakat.","s":5},{"t":"Menjelaskan ke warga bahwa ia sudah menjalani proses hukum dan layak diberi kesempatan.","s":4},{"t":"Diam saja agar tidak terseret masalah.","s":3},{"t":"Ikut menuntut ia ditangkap lagi demi rasa aman.","s":2},{"t":"Merekam ceritanya diam-diam lalu menyebarkannya ke grup warga.","s":1}], "ex":"Deportan yang telah menjalani proses hukum tidak boleh dihukum dua kali oleh masyarakat; yang dibutuhkan adalah pembinaan terkoordinasi, bukan stigma atau persekusi."},
{"id":"TKP-5055", "q":"Seorang WNI yang dideportasi karena menjadi kombatan kelompok ekstrem di luar negeri meminta surat keterangan berkelakuan baik dari kelurahan tempat Anda bertugas untuk melamar kerja. Sikap Anda?", "opts":[{"t":"Memproses sesuai prosedur sambil berkoordinasi dengan kepolisian/BNPT mengenai status pembinaannya sebelum surat diterbitkan.","s":5},{"t":"Memproses sesuai prosedur karena ia sudah menyelesaikan kewajiban hukumnya.","s":4},{"t":"Menolak menerbitkan surat dengan alasan ia mantan kombatan.","s":3},{"t":"Menerbitkan surat tanpa verifikasi apa pun agar cepat selesai.","s":2},{"t":"Memungut biaya tambahan karena menganggap kasusnya 'berat'.","s":1}], "ex":"Pelayanan administrasi untuk deportan harus prosedural sekaligus terkoordinasi dengan aparat; penolakan atau pungutan liar sama-sama melanggar prinsip pelayanan publik."},
{"id":"TKP-5056", "q":"Di bandara tempat Anda bertugas, seorang deportan yang baru tiba menolak mengikuti pendataan dengan alasan ia sudah 'bertobat' dan tidak mau dicap ekstrem. Sikap Anda sebagai petugas?", "opts":[{"t":"Menjelaskan dengan tegas namun santun bahwa pendataan adalah kewajiban hukum, lalu melaksanakannya sesuai SOP dan melaporkannya ke atasan.","s":5},{"t":"Menjelaskan bahwa pendataan adalah kewajiban hukum lalu melaksanakannya sesuai SOP.","s":4},{"t":"Membiarkannya lewat agar tidak ribut di area kedatangan.","s":3},{"t":"Memaksanya dengan kasar agar cepat selesai.","s":2},{"t":"Meminta 'uang damai' agar ia bisa lewat tanpa pendataan.","s":1}], "ex":"Pendataan deportan adalah kewajiban hukum yang tidak bisa ditawar; petugas wajib tegas, santun, prosedural, dan menolak segala bentuk pungli."},
{"id":"TKP-5057", "q":"Kelompok diaspora Indonesia di negara tempat Anda bertugas sebagai atase melaporkan adanya perekrutan WNI oleh jaringan ekstrem lintas negara lewat komunitas pengajian. Sikap Anda?", "opts":[{"t":"Mendokumentasikan laporan itu dan meneruskannya ke KBRI, kepolisian setempat, serta BNPT untuk ditindaklanjuti.","s":5},{"t":"Mendokumentasikan laporan itu dan meneruskannya ke KBRI untuk ditindaklanjuti.","s":4},{"t":"Menasihati diaspora agar menjauhi pengajian tersebut tanpa laporan resmi.","s":3},{"t":"Menganggapnya urusan internal komunitas diaspora.","s":2},{"t":"Mengabaikannya karena di luar wilayah kerja instansi Anda.","s":1}], "ex":"Perekrutan lintas negara oleh jaringan ekstrem adalah ancaman serius yang wajib dilaporkan berjenjang hingga ke aparat dan BNPT, bukan sekadar dihindari."},
{"id":"TKP-5058", "q":"Teman sekampus Anda yang kuliah di luar negeri mengabarkan ia diajak seniornya bergabung ke sel ekstrem yang merekrut mahasiswa Indonesia. Ia bingung dan meminta saran Anda. Sikap Anda?", "opts":[{"t":"Menasihatinya menolak tegas, menyimpan bukti ajakan, dan melaporkannya ke KBRI serta aparat keamanan.","s":5},{"t":"Menasihatinya menolak ajakan itu dan memutus kontak dengan seniornya.","s":4},{"t":"Menasihatinya pura-pura setuju agar tidak dimusuhi.","s":3},{"t":"Mengatakan itu pilihannya sendiri sebagai orang dewasa.","s":2},{"t":"Malah tertarik dan meminta dikenalkan ke seniornya.","s":1}], "ex":"Ajakan bergabung ke sel ekstrem harus ditolak dan dilaporkan dengan bukti ke KBRI dan aparat; sikap pura-pura setuju justru membahayakan keselamatan."},
{"id":"TKP-5059", "q":"Seorang deportan perempuan dengan dua anak kecil meminta bantuan sosial ke dinas tempat Anda bekerja. Ia mengaku dulu ikut suaminya ke zona konflik kelompok ekstrem karena terpaksa. Sikap Anda?", "opts":[{"t":"Memproses bantuan sesuai prosedur, merujuknya ke program perlindungan korban dan pembinaan, serta berkoordinasi dengan aparat terkait statusnya.","s":5},{"t":"Memproses bantuan sesuai prosedur seperti warga lain yang membutuhkan.","s":4},{"t":"Menolak membantu karena latar belakangnya berisiko.","s":3},{"t":"Membantu tetapi menyebarkan kisahnya ke media agar dapat donasi lebih.","s":2},{"t":"Mempersulit prosesnya agar ia jera.","s":1}], "ex":"Deportan perempuan dan anak-anak adalah kelompok rentan yang butuh bantuan prosedural plus rujukan pembinaan; penolakan atau eksploitasi kisahnya melanggar etika pelayanan."},
{"id":"TKP-5060", "q":"Dalam razia dokumen di perusahaan tempat Anda bekerja, ditemukan seorang TKA ilegal yang terindikasi pernah menjadi fasilitator dana jaringan teroris lintas negara. Sikap Anda sebagai HRD?", "opts":[{"t":"Mengamankan temuan itu, melaporkannya ke pimpinan dan kepolisian/imigrasi, serta menghentikan sementara aksesnya ke sistem perusahaan.","s":5},{"t":"Melaporkannya ke pimpinan dan kepolisian untuk ditindaklanjuti.","s":4},{"t":"Memberhentikannya diam-diam tanpa laporan agar nama perusahaan tidak tercoreng.","s":3},{"t":"Membiarkannya bekerja karena kinerjanya bagus.","s":2},{"t":"Memerasnya dengan ancaman laporan agar ia membayar sejumlah uang.","s":1}], "ex":"Indikasi fasilitator dana terorisme wajib dilaporkan ke kepolisian dan imigrasi; menutupinya atau memerasnya adalah pelanggaran hukum yang serius."},
{"id":"TKP-5061", "q":"Keluarga deportan di kampung Anda dikucilkan warga; anak-anaknya diejek 'anak teroris' di sekolah hingga trauma. Sebagai ASN dan tokoh masyarakat, sikap Anda?", "opts":[{"t":"Menggalang tokoh agama, guru, dan aparat untuk program penerimaan, serta memastikan anak-anaknya mendapat pendampingan psikososial.","s":5},{"t":"Menegur warga yang mengejek dan mengajak mereka bersikap adil pada anak-anak itu.","s":4},{"t":"Membiarkannya karena itu risiko yang harus ditanggung keluarganya.","s":3},{"t":"Menasihati keluarga itu pindah kampung saja.","s":2},{"t":"Ikut menjauhi keluarga itu agar tidak dicap pro-ekstrem.","s":1}], "ex":"Anak-anak deportan adalah korban yang butuh perlindungan dan pendampingan; pengucilan justru menyuburkan dendam yang bisa dimanfaatkan perekrut ekstrem."},
{"id":"TKP-5062", "q":"Seorang jurnalis asing meminta Anda sebagai ASN menjadi narasumber tentang jaringan deportan ekstrem di daerah Anda, dengan imbalan liputan yang 'menguntungkan citra instansi'. Sikap Anda?", "opts":[{"t":"Menolak menjadi narasumber tanpa izin pimpinan dan mengarahkannya ke humas/pejabat berwenang sesuai SOP kehumasan.","s":5},{"t":"Menolak halus karena bukan kewenangan Anda berbicara ke media asing.","s":4},{"t":"Bersedia dengan syarat tidak menyebut nama Anda.","s":3},{"t":"Bersedia asalkan imbalannya jelas.","s":2},{"t":"Memberikan data internal deportan agar liputannya 'lengkap'.","s":1}], "ex":"ASN dilarang menjadi narasumber media — apalagi asing — tanpa izin pimpinan; data deportan adalah informasi sensitif yang tidak boleh dibocorkan."},
{"id":"TKP-5063", "q":"Di pelabuhan tempat Anda bertugas, seorang ABK WNI yang baru dideportasi dari luar negeri karena dugaan keterlibatan jaringan ekstrem melamar kerja di kapal lain dengan identitas berbeda. Sikap Anda?", "opts":[{"t":"Menahan prosesnya, memverifikasi identitasnya, dan melaporkannya ke syahbandar serta kepolisian.","s":5},{"t":"Menolak lamarannya dan melaporkannya ke syahbandar.","s":4},{"t":"Membiarkannya karena kekurangan ABK memang tinggi.","s":3},{"t":"Meloloskannya asal ia membayar 'biaya percepatan'.","s":2},{"t":"Membantunya membuat identitas baru agar bisa bekerja.","s":1}], "ex":"Dugaan pemalsuan identitas oleh deportan wajib diverifikasi dan dilaporkan; meloloskannya membahayakan keamanan pelayaran dan melanggar hukum."},
{"id":"TKP-5064", "q":"Komunitas diaspora meminta Anda membantu memulangkan WNI yang terjebak di kamp penampungan eks kombatan di luar negeri dan diduga masih terpapar paham ekstrem. Sikap Anda?", "opts":[{"t":"Mengarahkan mereka ke mekanisme resmi pemulangan pemerintah (KBRI/Kemlu/BNPT) dan menolak jalur tidak resmi.","s":5},{"t":"Mengarahkan mereka ke KBRI untuk mengikuti prosedur resmi.","s":4},{"t":"Menyarankan memakai jasa agen perjalanan swasta agar cepat.","s":3},{"t":"Menolak membantu karena terlalu berisiko.","s":2},{"t":"Menawarkan 'jalur khusus' berbayar untuk mempercepat pemulangan.","s":1}], "ex":"Pemulangan WNI dari zona konflik hanya boleh lewat mekanisme resmi negara yang mencakup skrining dan deradikalisasi; jalur tidak resmi berbahaya dan ilegal."},
{"id":"TKP-5065", "q":"Seorang dosen tamu dari luar negeri yang diundang kampus tempat Anda bekerja diketahui menyebarkan materi ekstrem lewat kuliah umumnya. Sikap Anda sebagai panitia?", "opts":[{"t":"Menghentikan kerja sama, menarik undangannya, dan melaporkan materi serta aktivitasnya ke pimpinan kampus dan aparat.","s":5},{"t":"Menghentikan kerja sama dan menarik undangannya.","s":4},{"t":"Membiarkan kuliahnya selesai karena sudah terlanjur diundang.","s":3},{"t":"Hanya menegur panitia lain agar lebih selektif tanpa tindakan nyata.","s":2},{"t":"Merekam kuliahnya untuk disebarluaskan karena 'menarik'.","s":1}], "ex":"Penyebaran paham ekstrem di kampus harus dihentikan seketika dan dilaporkan; pembiaran dengan alasan keterlanjuran sama dengan memfasilitasi radikalisasi."},
{"id":"TKP-5066", "q":"Tetangga Anda menerima kiriman uang rutin dari kerabatnya di luar negeri yang diduga untuk mendanai aktivitas kelompok ekstrem. Ia meminta Anda merahasiakannya. Sikap Anda?", "opts":[{"t":"Menolak merahasiakan dan melaporkannya ke aparat (kepolisian/PPATK) karena diduga pendanaan terorisme.","s":5},{"t":"Menasihatinya menghentikan penerimaan dana itu dan melaporkannya ke aparat.","s":4},{"t":"Merahasiakannya karena ia tetangga baik.","s":3},{"t":"Meminta bagian dari kiriman itu sebagai 'upah tutup mulut'.","s":2},{"t":"Ikut membantu menyalurkan dana itu ke pihak lain.","s":1}], "ex":"Dugaan pendanaan terorisme lintas negara wajib dilaporkan ke aparat; merahasiakan atau ikut menyalurkan sama dengan terlibat tindak pidana terorisme."},
{"id":"TKP-5067", "q":"Dalam program pertukaran pelajar, seorang siswa asing di sekolah tempat Anda mengajar menyebarkan selebaran ekstrem kepada siswa Indonesia. Sikap Anda sebagai guru?", "opts":[{"t":"Menyita selebarannya, melaporkan ke kepala sekolah, dan berkoordinasi dengan pihak berwenang serta kedutaan terkait.","s":5},{"t":"Menyita selebarannya dan melaporkannya ke kepala sekolah.","s":4},{"t":"Menasihati siswa itu secara pribadi agar tidak mengulangi.","s":3},{"t":"Membiarkannya karena ia tamu dan akan segera pulang.","s":2},{"t":"Menganggapnya bahan diskusi menarik untuk kelas.","s":1}], "ex":"Propaganda ekstrem di lingkungan sekolah harus disita dan dilaporkan berjenjang; pembiaran membahayakan siswa Indonesia yang menjadi sasaran."},
{"id":"TKP-5068", "q":"Seorang mantan kombatan kelompok ekstrem yang dideportasi ingin menjadi penceramah di masjid dekat rumah Anda dengan tema 'pengalaman hijrah'. Takmir meminta pendapat Anda. Sikap Anda?", "opts":[{"t":"Menyarankan takmir menerimanya dengan syarat materi ceramah diverifikasi takmir dan ia terdaftar dalam program pembinaan aparat.","s":5},{"t":"Menyarankan takmir menerimanya selama temanya positif dan tidak menyimpang.","s":4},{"t":"Menolak mentah-mentah tanpa memberi kesempatan.","s":3},{"t":"Mendukung penuh tanpa verifikasi apa pun.","s":2},{"t":"Memanfaatkannya untuk menarik jamaah dari masjid lain.","s":1}], "ex":"Mantan kombatan boleh berdakwah bila materinya terverifikasi dan ia dalam pembinaan; penolakan total menutup pintu tobat, penerimaan tanpa verifikasi membuka celah propaganda."},
{"id":"TKP-5069", "q":"Perusahaan ekspedisi tempat Anda bekerja menerima paket rutin ke luar negeri dari pelanggan yang terindikasi menjadi kurir logistik jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Melaporkan pola pengiriman mencurigakan itu ke pimpinan dan kepolisian sesuai ketentuan pelaporan transaksi mencurigakan.","s":5},{"t":"Melaporkannya ke pimpinan untuk ditindaklanjuti.","s":4},{"t":"Tetap melayani karena bisnis adalah bisnis.","s":3},{"t":"Menolak melayani tanpa laporan agar tidak terlibat.","s":2},{"t":"Menaikkan tarifnya diam-diam karena 'berisiko'.","s":1}], "ex":"Indikasi logistik jaringan ekstrem wajib dilaporkan ke kepolisian; tetap melayani berarti memfasilitasi, menolak tanpa lapor berarti membiarkan jaringan berjalan."},
{"id":"TKP-5070", "q":"Seorang deportan yang sudah ikut deradikalisasi melamar sebagai penyuluh di program kontra-narasi pemerintah. Sebagian panitia menolak karena rekam jejaknya. Sikap Anda sebagai ketua panitia?", "opts":[{"t":"Tetap memprosesnya dengan penilaian objektif dan verifikasi pembinaannya, karena pengalaman mantan pelaku justru efektif untuk kontra-narasi.","s":5},{"t":"Tetap memprosesnya dengan penilaian objektif seperti pelamar lain.","s":4},{"t":"Menolaknya demi menjaga citra program.","s":3},{"t":"Menerimanya tanpa verifikasi karena butuh cepat.","s":2},{"t":"Membocorkan rekam jejaknya ke media agar ia gagal.","s":1}], "ex":"Mantan pelaku yang terverifikasi deradikalisasinya adalah aset berharga program kontra-narasi; penolakan berbasis stigma menyia-nyiakan potensi pencegahan."},
{"id":"TKP-5071", "q":"Di asrama pekerja migran tempat Anda menjadi pengurus, ditemukan selebaran rekrutmen kelompok ekstrem berbahasa Indonesia yang menyasar PMI. Sikap Anda?", "opts":[{"t":"Menyita selebarannya, melaporkan ke pengelola asrama, KBRI, dan aparat, serta memberi penyuluhan anti-radikalisme ke para PMI.","s":5},{"t":"Menyita selebarannya dan melaporkannya ke pengelola asrama.","s":4},{"t":"Membuang selebarannya diam-diam tanpa laporan.","s":3},{"t":"Membiarkannya karena bukan urusan pengurus asrama.","s":2},{"t":"Mengabaikannya karena sibuk dengan urusan lain.","s":1}], "ex":"PMI adalah sasaran empuk perekrutan ekstrem lintas negara; temuan selebaran harus dilaporkan berjenjang dan ditindaklanjuti dengan penyuluhan."},
{"id":"TKP-5072", "q":"Seorang WNI yang dideportasi karena menjadi admin kanal propaganda teroris meminta Anda — temannya — menjadi penjamin administrasinya. Sikap Anda?", "opts":[{"t":"Menolak menjadi penjamin dan melaporkannya ke aparat agar status pembinaannya jelas sebelum dibebaskan beraktivitas.","s":5},{"t":"Menolak menjadi penjamin karena risikonya terlalu besar.","s":4},{"t":"Bersedia menjadi penjamin karena kasihan padanya.","s":3},{"t":"Bersedia asalkan ia berjanji tidak mengulangi.","s":2},{"t":"Bersedia dengan imbalan sejumlah uang.","s":1}], "ex":"Menjadi penjamin eks admin propaganda teroris tanpa kejelasan pembinaan sangat berisiko; penolakan dan pelaporan adalah langkah yang bertanggung jawab."},
{"id":"TKP-5073", "q":"Lembaga kursus bahasa tempat Anda bekerja menerima tawaran kerja sama 'beasiswa penuh' dari yayasan asing yang terindikasi menjadi kedok rekrutmen ekstrem. Sikap Anda?", "opts":[{"t":"Menolak tawaran itu dan melaporkannya ke pimpinan serta aparat karena indikasi kedok rekrutmen ekstrem.","s":5},{"t":"Menolak tawaran itu karena mencurigakan.","s":4},{"t":"Menerimanya karena menguntungkan lembaga dan siswa.","s":3},{"t":"Menerimanya tetapi merahasiakan dari siswa.","s":2},{"t":"Meminta komisi pribadi agar kerja sama disetujui.","s":1}], "ex":"Tawaran beasiswa dari yayasan terindikasi ekstrem adalah modus rekrutmen klasik; harus ditolak dan dilaporkan, bukan diterima demi keuntungan."},
{"id":"TKP-5074", "q":"Dalam forum daring diaspora Indonesia, seorang anggota terang-terangan menggalang dana untuk 'perjuangan' kelompok bersenjata ekstrem di luar negeri. Sikap Anda sebagai anggota forum?", "opts":[{"t":"Menolak ikut, menyimpan bukti, dan melaporkannya ke admin forum serta aparat penegak hukum.","s":5},{"t":"Menolak ikut dan keluar dari forum tersebut.","s":4},{"t":"Diam saja karena tidak ikut menyumbang.","s":3},{"t":"Menyumbang sedikit agar tidak dicap tidak solid.","s":2},{"t":"Ikut menyebarkan galangan dana itu ke forum lain.","s":1}], "ex":"Penggalangan dana untuk kelompok bersenjata ekstrem adalah pendanaan terorisme; wajib ditolak dan dilaporkan dengan bukti, bukan sekadar dihindari."},
{"id":"TKP-5075", "q":"Seorang deportan anak di bawah umur yang dipulangkan dari kamp konflik kelompok teroris di luar negeri akan ditempatkan di sekolah dekat rumah Anda. Sebagian orang tua murid menolak. Sikap Anda sebagai komite sekolah?", "opts":[{"t":"Mendukung penempatannya dengan pendampingan psikolog dan pembinaan khusus, sambil mengedukasi orang tua murid agar tidak menstigma.","s":5},{"t":"Mendukung penempatannya dan memintanya diperlakukan sama seperti murid lain.","s":4},{"t":"Netral dan menyerahkan keputusan ke pihak sekolah.","s":3},{"t":"Ikut menolak demi ketenangan sekolah.","s":2},{"t":"Mengusulkan ia disekolahkan di tempat khusus yang terisolasi.","s":1}], "ex":"Anak deportan adalah korban konflik yang butuh pendidikan dan pendampingan, bukan stigma; penolakan kolektif melanggar hak anak atas pendidikan."},
{"id":"TKP-5076", "q":"Seorang pembicara dalam diskusi kampus tempat Anda menjadi moderator menyatakan 'Pancasila sudah usang dan harus diganti sistem khilafah' dengan dalih kebebasan berpendapat dan kritik intelektual. Sikap Anda?", "opts":[{"t":"Menegaskan bahwa kritik boleh tetapi ajakan mengganti Pancasila melanggar konstitusi, lalu melaporkan pembicara itu ke rektorat dan aparat.","s":5},{"t":"Menegaskan batas kritik yang dibolehkan dan menutup diskusi bila pembicara terus memprovokasi.","s":4},{"t":"Membiarkan diskusi berlanjut dengan alasan kebebasan akademik.","s":3},{"t":"Ikut mengangguk agar tidak dianggap anti-kritik.","s":2},{"t":"Mendukung pernyataannya dan menyebarkan potongan videonya.","s":1}], "ex":"Kebebasan berpendapat tidak mencakup ajakan mengganti dasar negara; moderator wajib menegakkan batas konstitusional dan melaporkan provokator ekstrem."},
{"id":"TKP-5077", "q":"Rekan dosen Anda menulis opini di media kampus bahwa demokrasi Pancasila adalah 'sistem kufur' yang harus ditinggalkan, dikemas sebagai kajian filsafat politik yang bermuatan ekstrem. Sikap Anda sebagai kolega?", "opts":[{"t":"Melaporkan tulisan itu ke pimpinan kampus karena mengandung ajakan ekstrem mengganti ideologi negara.","s":5},{"t":"Menegur rekan itu dan memintanya mencabut tulisan tersebut.","s":4},{"t":"Membiarkannya dengan alasan kebebasan akademik.","s":3},{"t":"Ikut membagikan tulisannya karena dinilai 'berani'.","s":2},{"t":"Mengundangnya menjadi pembicara kajian rutin jurusan.","s":1}], "ex":"Opini yang mengkafirkan Pancasila dan mengajak meninggalkannya adalah propaganda ekstrem berkedok akademik yang wajib dilaporkan, bukan dilindungi atas nama kebebasan."},
{"id":"TKP-5078", "q":"Dalam grup diskusi ASN, seorang anggota rutin membagikan 'kajian kritis' yang intinya menyebut Pancasila buatan manusia sehingga boleh diganti khilafah. Sikap Anda sebagai anggota grup?", "opts":[{"t":"Membantah argumennya secara terbuka dan melaporkan aktivitasnya ke atasan/BKPSDM.","s":5},{"t":"Membantah argumennya dan memintanya berhenti menyebar di grup ASN.","s":4},{"t":"Keluar dari grup agar tidak terpapar.","s":3},{"t":"Diam saja karena takut didebat.","s":2},{"t":"Ikut menyebarkannya ke grup lain karena isinya 'masuk akal'.","s":1}], "ex":"Narasi anti-Pancasila berkedok kajian kritis harus dibantah dan dilaporkan; keluar diam-diam tanpa laporan membiarkan radikalisasi berlanjut di kalangan ASN."},
{"id":"TKP-5079", "q":"Seorang tokoh yang diundang sebagai narasumber seminar kebangsaan di instansi Anda justru menyampaikan ceramah bahwa Pancasila 'gagal' dan solusinya khilafah. Sikap Anda sebagai peserta?", "opts":[{"t":"Menyampaikan keberatan resmi ke panitia dan melaporkan isi ceramahnya ke pimpinan instansi.","s":5},{"t":"Menyampaikan keberatan resmi ke panitia seminar.","s":4},{"t":"Tetap duduk mendengarkan sampai selesai tanpa reaksi.","s":3},{"t":"Merekam dan menyebarkannya karena viral.","s":2},{"t":"Berdiri dan bertepuk tangan mendukungnya.","s":1}], "ex":"Narasumber yang menyalahgunakan forum kebangsaan untuk propaganda anti-Pancasila harus diprotes resmi dan dilaporkan; merekam untuk disebar justru memperluas propaganda."},
{"id":"TKP-5080", "q":"Buku 'kritik Pancasila' yang isinya ajakan terselubung mengganti ideologi negara dengan khilafah beredar di perpustakaan kantor Anda. Sikap Anda?", "opts":[{"t":"Melaporkan peredaran buku itu ke pimpinan dan menariknya dari rak sambil menunggu verifikasi aparat.","s":5},{"t":"Melaporkan peredaran buku itu ke pimpinan perpustakaan.","s":4},{"t":"Membiarkannya karena pembaca bisa menilai sendiri.","s":3},{"t":"Meminjamnya untuk dibaca di rumah.","s":2},{"t":"Merekomendasikannya ke rekan-rekan sebagai bacaan 'kritis'.","s":1}], "ex":"Buku propaganda anti-Pancasila berkedok kritik harus dilaporkan dan ditarik dari fasilitas publik; dalih 'pembaca bisa menilai sendiri' mengabaikan bahaya radikalisasi."},
{"id":"TKP-5081", "q":"Anak Anda pulang sekolah bercerita gurunya mengajarkan bahwa 'Pancasila itu thaghut' dengan dalih tafsir kritis yang ekstrem. Sikap Anda sebagai orang tua?", "opts":[{"t":"Mengonfirmasi ke sekolah, melaporkan guru itu ke kepala sekolah dan dinas pendidikan bila terbukti menyebarkan paham ekstrem.","s":5},{"t":"Mengonfirmasi ke sekolah dan meminta guru itu ditegur.","s":4},{"t":"Menasihati anak agar tidak percaya begitu saja.","s":3},{"t":"Membiarkannya karena menghormati guru.","s":2},{"t":"Membenarkan ajaran guru itu di depan anak.","s":1}], "ex":"Guru yang menanamkan paham anti-Pancasila ke anak didik adalah pelanggaran berat yang wajib dilaporkan berjenjang; pembiaran meracuni generasi muda."},
{"id":"TKP-5082", "q":"Seorang penceramah di pengajian warga menyebut 'demokrasi Pancasila itu haram' dengan dalih dakwah kritis yang intoleran. Anda jamaah pengajian itu. Sikap Anda?", "opts":[{"t":"Menegur penceramah itu dan melaporkan ke takmir serta aparat bila ia terus menyebarkan ajaran ekstrem.","s":5},{"t":"Menegur penceramah itu dan mengusulkan takmir menggantinya.","s":4},{"t":"Pindah pengajian lain tanpa menegur.","s":3},{"t":"Tetap hadir karena ceramahnya 'tegas'.","s":2},{"t":"Mengundangnya ceramah di acara keluarga Anda.","s":1}], "ex":"Dakwah yang mengharamkan Pancasila adalah propaganda ekstrem berkedok agama; jamaah wajib menegur dan melaporkan, bukan sekadar pindah pengajian."},
{"id":"TKP-5083", "q":"Teman Anda membuat thread media sosial 'bedah kritis Pancasila' yang ujung-ujungnya mengajak followers mendukung khilafah. Ia meminta Anda me-retweet. Sikap Anda?", "opts":[{"t":"Menolak me-retweet, menegurnya, dan melaporkan akunnya sebagai penyebar paham ekstrem.","s":5},{"t":"Menolak me-retweet dan menegurnya secara pribadi.","s":4},{"t":"Mengabaikan permintaannya tanpa komentar.","s":3},{"t":"Me-retweet agar pertemanan tetap baik.","s":2},{"t":"Me-retweet plus menambahkan komentar dukungan.","s":1}], "ex":"Konten anti-Pancasila berkedok bedah kritis harus ditolak dan dilaporkan; me-retweet demi pertemanan sama dengan ikut menyebarkan propaganda ekstrem."},
{"id":"TKP-5084", "q":"Dalam lomba debat mahasiswa yang Anda juri, sebuah tim berargumen 'Pancasila harus diganti khilafah demi kemajuan' sebagai strategi debat. Sikap Anda?", "opts":[{"t":"Mendiskualifikasi argumennya karena melanggar batas konstitusional dan melaporkan tim itu ke panitia serta kampus.","s":5},{"t":"Memberi nilai rendah dengan catatan argumennya inkonstitusional.","s":4},{"t":"Menilainya murni dari teknik debat tanpa melihat isinya.","s":3},{"t":"Memberi nilai tinggi karena argumennya 'berani dan orisinal'.","s":2},{"t":"Mengundangnya berdebat di forum yang lebih besar.","s":1}], "ex":"Kebebasan berdebat tidak membenarkan argumen inkonstitusional; juri wajib menegakkan batas dan melaporkan, bukan menilai seolah kontennya netral."},
{"id":"TKP-5085", "q":"Seorang kolumnis media daring langganan Anda rutin menulis bahwa 'Pancasila buatan kolonial pikir' dan mengajak pembaca berpikir tentang khilafah sebagai alternatif. Sikap Anda sebagai pembaca?", "opts":[{"t":"Berhenti berlangganan, menulis sanggahan, dan melaporkan medianya ke Dewan Pers serta aparat bila mengandung ajakan ekstrem.","s":5},{"t":"Berhenti berlangganan dan menulis sanggahan di kolom komentar.","s":4},{"t":"Tetap membaca sebagai 'wawasan pembanding'.","s":3},{"t":"Membagikan artikelnya agar banyak yang baca.","s":2},{"t":"Menghubunginya untuk kolaborasi menulis.","s":1}], "ex":"Kolom yang sistematis mendeligitimasi Pancasila demi khilafah adalah propaganda yang harus dilawan dengan sanggahan dan laporan resmi, bukan dikonsumsi diam-diam."},
{"id":"TKP-5086", "q":"Di kelas pelatihan kepemimpinan ASN, seorang peserta berargumen 'Pancasila menghambat syariat' yang ekstrem dan mengajak peserta lain diskusi lanjutan di luar kelas. Sikap Anda sebagai peserta?", "opts":[{"t":"Menolak ajakannya dan melaporkan peserta itu ke penyelenggara diklat.","s":5},{"t":"Menolak ajakannya dengan tegas di depan peserta lain.","s":4},{"t":"Diam saja agar tidak ribut di kelas.","s":3},{"t":"Ikut diskusi lanjutannya karena penasaran.","s":2},{"t":"Ikut menyebarkan undangannya ke peserta lain.","s":1}], "ex":"Ajakan diskusi lanjutan bermuatan anti-Pancasila di forum diklat ASN adalah modus rekrutmen yang wajib ditolak dan dilaporkan ke penyelenggara."},
{"id":"TKP-5087", "q":"Film dokumenter 'independen' yang diputar di komunitas Anda menyimpulkan 'Pancasila proyek gagal' dan menawarkan khilafah sebagai solusi, dikemas sebagai karya kritis. Sikap Anda sebagai anggota komunitas?", "opts":[{"t":"Mengkritik isi filmnya secara terbuka dan melaporkan pemutarannya bila bermuatan propaganda ekstrem ke aparat.","s":5},{"t":"Mengkritik isi filmnya dalam diskusi setelah pemutaran.","s":4},{"t":"Menonton saja tanpa berkomentar.","s":3},{"t":"Memuji filmnya sebagai karya berani.","s":2},{"t":"Membantu menyebarkan filmnya ke komunitas lain.","s":1}], "ex":"Karya yang mendeligitimasi Pancasila demi menawarkan khilafah adalah propaganda ekstrem berkedok seni; harus dikritik terbuka dan dilaporkan bila perlu."},
{"id":"TKP-5088", "q":"Seorang alumni sukses mengisi kuliah umum di kampus Anda dengan materi 'kegagalan Pancasila' yang berujung ajakan mendukung khilafah. Sikap Anda sebagai dosen pendamping?", "opts":[{"t":"Menginterupsi secara santun, meluruskan di depan mahasiswa, dan melaporkan ke rektorat.","s":5},{"t":"Meluruskan materinya di depan mahasiswa setelah sesi selesai.","s":4},{"t":"Membiarkannya karena ia alumni berpengaruh.","s":3},{"t":"Mengundangnya lagi karena mahasiswanya antusias.","s":2},{"t":"Mengunggah videonya ke media sosial kampus.","s":1}], "ex":"Kuliah umum bukan panggung propaganda anti-Pancasila; dosen pendamping wajib meluruskan di tempat dan melaporkan, tanpa pandang status pembicara."},
{"id":"TKP-5089", "q":"Grup kajian daring yang Anda ikuti perlahan berubah: adminnya mulai menyelipkan materi 'Pancasila vs khilafah' dengan dalih diskusi terbuka. Sikap Anda?", "opts":[{"t":"Keluar dari grup sambil melaporkan adminnya sebagai penyebar paham ekstrem.","s":5},{"t":"Keluar dari grup dan memperingatkan anggota lain.","s":4},{"t":"Tetap di grup untuk 'memantau' tanpa bertindak.","s":3},{"t":"Ikut berdiskusi dengan argumen membela khilafah.","s":2},{"t":"Membantu admin menyebarkan materinya.","s":1}], "ex":"Grup kajian yang disusupi propaganda anti-Pancasila harus ditinggalkan dan adminnya dilaporkan; 'memantau' pasif tanpa laporan sama dengan membiarkan radikalisasi."},
{"id":"TKP-5090", "q":"Seorang calon legislatif dalam kampanyenya menyatakan 'Pancasila perlu ditinjau ulang total' dengan nada mengarah ke khilafah. Anda warga di daerah pemilihannya. Sikap Anda?", "opts":[{"t":"Tidak memilihnya dan melaporkan pernyataannya ke Bawaslu serta aparat bila mengandung ajakan inkonstitusional.","s":5},{"t":"Tidak memilihnya karena pernyataannya berbahaya.","s":4},{"t":"Tetap netral karena itu haknya berkampanye.","s":3},{"t":"Memilihnya karena dianggap berani mengkritik.","s":2},{"t":"Menjadi tim suksesnya.","s":1}], "ex":"Kampanye yang mengarah pada penggantian Pancasila melanggar prinsip pemilu demokratis; warga wajib menolak lewat suara dan melaporkannya ke Bawaslu."},
{"id":"TKP-5091", "q":"Poster 'Diskusi Kritis: Masa Depan Pancasila' yang ditempel di kampus ternyata berisi ajakan terselubung bergabung ke gerakan pro-khilafah. Sikap Anda sebagai mahasiswa?", "opts":[{"t":"Melaporkan poster itu ke pihak kampus dan mencopotnya bila berwenang, serta memperingatkan teman-teman.","s":5},{"t":"Melaporkan poster itu ke pihak kampus.","s":4},{"t":"Mengabaikannya karena banyak poster di kampus.","s":3},{"t":"Datang ke diskusinya karena penasaran.","s":2},{"t":"Ikut menempelkan poster serupa di fakultas lain.","s":1}], "ex":"Poster diskusi yang menjadi kedok rekrutmen pro-khilafah harus dilaporkan dan dicopot; rasa penasaran tanpa kewaspadaan adalah pintu masuk radikalisasi."},
{"id":"TKP-5092", "q":"Seorang intelektual publik yang Anda kagumi menyatakan di televisi bahwa 'Pancasila tidak relevan lagi' dan menyiratkan khilafah sebagai jawaban. Sikap Anda sebagai penonton?", "opts":[{"t":"Tetap kritis, tidak terpengaruh, dan melaporkan bila pernyataannya mengandung ajakan inkonstitusional yang sistematis.","s":5},{"t":"Tetap kritis dan mendiskusikannya dengan kerangka konstitusional.","s":4},{"t":"Menganggapnya sekadar opini pribadi.","s":3},{"t":"Mulai meragukan Pancasila karena kagum padanya.","s":2},{"t":"Menyebarkan potongan videonya sebagai 'pencerahan'.","s":1}], "ex":"Kekaguman pada tokoh tidak boleh melumpuhkan nalar konstitusional; pernyataan publik yang mendeligitimasi Pancasila harus disikapi kritis dan dilaporkan bila sistematis."},
{"id":"TKP-5093", "q":"Dalam rapat RT, seorang warga mengusulkan 'aturan kampung berdasarkan khilafah' dengan dalih Pancasila tidak mengatur detail kehidupan. Sikap Anda sebagai warga?", "opts":[{"t":"Menolak usulan itu dengan tegas karena bertentangan dengan NKRI dan melaporkannya ke RW serta aparat bila ia memaksa.","s":5},{"t":"Menolak usulan itu dengan alasan melanggar aturan negara.","s":4},{"t":"Diam saja karena tidak mau berselisih dengan tetangga.","s":3},{"t":"Setuju saja agar rapat cepat selesai.","s":2},{"t":"Mendukung dan menawarkan diri menyusun aturannya.","s":1}], "ex":"Usulan aturan berbasis khilafah di tingkat RT adalah infiltrasi ideologi ekstrem ke ranah terkecil negara; wajib ditolak tegas dan dilaporkan bila dipaksakan."},
{"id":"TKP-5094", "q":"Kakak kelas Anda mengajak 'bedah buku' yang ternyata berisi doktrin ekstrem bahwa Pancasila adalah sistem thaghut yang wajib diperangi. Sikap Anda?", "opts":[{"t":"Menolak ikut, mengembalikan bukunya, dan melaporkan kakak kelas itu ke pihak kampus dan aparat.","s":5},{"t":"Menolak ikut dan mengembalikan bukunya.","s":4},{"t":"Ikut sekali untuk melihat isinya.","s":3},{"t":"Ikut rutin karena suasananya akrab.","s":2},{"t":"Mengajak teman-teman lain ikut serta.","s":1}], "ex":"Bedah buku doktrin anti-Pancasila adalah modus rekrutmen klasik; sekali ikut saja sudah berisiko, apalagi mengajak orang lain."},
{"id":"TKP-5095", "q":"Seorang penceramah kondang di media sosial menyatakan 'ikut Pancasila itu syirik' dengan dalih kajian tauhid yang ekstrem. Video Anda ditandai teman. Sikap Anda?", "opts":[{"t":"Tidak terpengaruh, menghapus tanda, dan melaporkan kontennya sebagai ujaran ekstrem.","s":5},{"t":"Tidak terpengaruh dan menghapus tanda dari video itu.","s":4},{"t":"Menontonnya sampai habis karena penasaran.","s":3},{"t":"Membagikannya ke grup keluarga untuk 'didiskusikan'.","s":2},{"t":"Menjadi pengikut setianya.","s":1}], "ex":"Kajian yang mensyirikkan Pancasila adalah takfirisme berkedok tauhid; kontennya wajib dilaporkan dan tidak boleh disebarluaskan meski untuk 'diskusi'."},
{"id":"TKP-5096", "q":"Dalam seminar daring internasional, pembicara asing mengajak peserta Indonesia 'meninggalkan Pancasila' menuju khilafah global. Sikap Anda sebagai peserta Indonesia?", "opts":[{"t":"Menyampaikan keberatan resmi di forum dan melaporkan ke panitia serta aparat terkait.","s":5},{"t":"Menyampaikan keberatan di kolom chat forum.","s":4},{"t":"Keluar diam-diam dari seminar.","s":3},{"t":"Tetap menyimak karena pembicaranya terkenal.","s":2},{"t":"Menghubunginya untuk kerja sama lanjutan.","s":1}], "ex":"Ajakan meninggalkan Pancasila di forum internasional adalah serangan ideologis lintas negara yang wajib diprotes resmi dan dilaporkan, bukan disimak pasif."},
{"id":"TKP-5097", "q":"Teman sekantor Anda mulai mengenakan atribut dan menyebarkan selebaran 'Pancasila sudah mati, saatnya khilafah' dengan dalih dakwah. Sikap Anda?", "opts":[{"t":"Menegurnya dan melaporkan ke atasan serta BKPSDM karena ASN dilarang menyebarkan paham anti-Pancasila.","s":5},{"t":"Menegurnya agar berhenti menyebar di lingkungan kantor.","s":4},{"t":"Menghindarinya agar tidak terlibat.","s":3},{"t":"Membiarkannya karena itu hak berekspresi.","s":2},{"t":"Ikut menyebarkan selebarannya.","s":1}], "ex":"ASN penyebar paham anti-Pancasila melanggar sumpah jabatan dan wajib dilaporkan ke BKPSDM; dalih dakwah tidak melindungi dari sanksi disiplin."},
{"id":"TKP-5098", "q":"Sebuah LSM asing menawarkan dana riset ke kampus Anda dengan syarat hasil kajiannya 'mengkritik Pancasila secara fundamental' dengan muatan ekstrem. Sikap Anda sebagai peneliti?", "opts":[{"t":"Menolak tawaran itu dan melaporkannya ke pimpinan kampus karena syaratnya mengarah pada delegitimasi ideologi negara.","s":5},{"t":"Menolak tawaran itu karena syaratnya tidak etis.","s":4},{"t":"Menerimanya tetapi menulis sesuai keyakinan sendiri.","s":3},{"t":"Menerimanya karena dana riset sulit didapat.","s":2},{"t":"Menerima dan memenuhi syaratnya demi dana lanjutan.","s":1}], "ex":"Dana riset bersyarat mendeligitimasi Pancasila adalah intervensi ideologis asing; peneliti berintegritas wajib menolak dan melaporkannya."},
{"id":"TKP-5099", "q":"Di perpustakaan daerah tempat Anda bertugas, donatur menyumbang ratusan buku 'kajian kritis ideologi' yang isinya propaganda anti-Pancasila yang ekstrem. Sikap Anda?", "opts":[{"t":"Menolak sumbangan itu dan melaporkannya ke kepala dinas serta aparat.","s":5},{"t":"Menolak sumbangan itu dengan alasan tidak sesuai koleksi.","s":4},{"t":"Menerimanya tetapi menyimpannya di gudang.","s":3},{"t":"Menerima dan memajangnya di rak umum.","s":2},{"t":"Menerima dan mempromosikannya ke pengunjung.","s":1}], "ex":"Sumbangan buku propaganda anti-Pancasila adalah infiltrasi ideologis ke fasilitas publik; wajib ditolak dan dilaporkan, bukan diterima lalu disembunyikan."},
{"id":"TKP-5100", "q":"Seorang tokoh masyarakat mengajak warga 'mengkaji ulang' Pancasila dalam forum yang ternyata berujung baiat mendukung khilafah. Anda hadir di forum itu. Sikap Anda?", "opts":[{"t":"Menolak baiat, meninggalkan forum, dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menolak baiat dan meninggalkan forum itu.","s":4},{"t":"Ikut baiat agar tidak dikucilkan warga.","s":3},{"t":"Tetap di forum karena penasaran kelanjutannya.","s":2},{"t":"Ikut baiat dengan keyakinan penuh.","s":1}], "ex":"Forum kajian yang berujung baiat khilafah adalah jebakan rekrutmen; satu-satunya sikap benar adalah menolak, pergi, dan melaporkan penyelenggaranya."}
,
{"id":"TKP-5101", "q":"Ormas kepemudaan tempat Anda menjadi pengurus disusupi anggota baru yang perlahan mengarahkan kegiatan ke doktrin ekstrem dan penolakan terhadap Pancasila. Sikap Anda sebagai pengurus?", "opts":[{"t":"Mengungkap penyusupan itu dalam rapat pengurus, memecat oknumnya sesuai AD/ART, dan melaporkannya ke aparat.","s":5},{"t":"Mengungkap penyusupan itu dan memecat oknumnya sesuai AD/ART.","s":4},{"t":"Mengundurkan diri diam-diam dari kepengurusan.","s":3},{"t":"Membiarkannya karena anggotanya banyak dan berpengaruh.","s":2},{"t":"Ikut mendukung arah barunya agar tetap populer.","s":1}], "ex":"Penyusupan paham ekstrem ke ormas harus dilawan lewat mekanisme organisasi dan laporan aparat; mengundurkan diri diam-diam membiarkan ormas dikuasai."},
{"id":"TKP-5102", "q":"Ketua karang taruna di kampung Anda tiba-tiba mewajibkan anggotanya mengikuti 'kaderisasi' bermuatan paham radikal dengan ancaman dikeluarkan. Sikap Anda sebagai anggota?", "opts":[{"t":"Menolak ikut, menggalang anggota lain yang keberatan, dan melaporkan ketua itu ke lurah serta aparat.","s":5},{"t":"Menolak ikut dan keluar dari karang taruna.","s":4},{"t":"Ikut saja agar tidak dikeluarkan.","s":3},{"t":"Membiarkannya karena itu urusan ketua.","s":2},{"t":"Ikut dan mengajak teman lain bergabung.","s":1}], "ex":"Kaderisasi bermuatan radikal di organisasi kepemudaan adalah penyalahgunaan wewenang yang wajib ditolak kolektif dan dilaporkan, bukan diikuti demi keanggotaan."},
{"id":"TKP-5103", "q":"Sebuah ormas baru mendaftar ke Kesbangpol tempat Anda bertugas; AD/ART-nya bagus, tetapi pengurusnya dikenal sebagai eksponen gerakan ekstrem. Sikap Anda sebagai petugas verifikasi?", "opts":[{"t":"Melakukan verifikasi faktual mendalam, berkoordinasi dengan aparat intelijen, dan merekomendasikan penolakan bila terbukti menjadi wadah ekstrem.","s":5},{"t":"Melakukan verifikasi faktual mendalam sebelum menerbitkan rekomendasi.","s":4},{"t":"Meloloskan karena dokumennya lengkap.","s":3},{"t":"Meloloskan dengan imbalan 'uang rokok'.","s":2},{"t":"Menolak tanpa verifikasi karena prasangka pribadi.","s":1}], "ex":"Verifikasi ormas wajib faktual dan terkoordinasi dengan aparat; meloloskan karena dokumen lengkap membuka pintu legalisasi wadah ekstrem."},
{"id":"TKP-5104", "q":"Komunitas hobi motor tempat Anda bergabung mulai diisi ceramah-ceramah yang mengajak anggotanya memusuhi pemerintah dengan dalih ekstrem. Sikap Anda?", "opts":[{"t":"Menegur penyelenggaranya, mengajak anggota lain menolak politisasi komunitas, dan melaporkan bila terus berlanjut.","s":5},{"t":"Menegur penyelenggaranya dan mengusulkan kembali ke agenda hobi.","s":4},{"t":"Keluar dari komunitas tanpa penjelasan.","s":3},{"t":"Tetap ikut karena teman-temannya asyik.","s":2},{"t":"Ikut menyebarkan ceramahnya ke komunitas lain.","s":1}], "ex":"Komunitas hobi yang dipolitisasi paham ekstrem harus diluruskan dari dalam dan dilaporkan; keluar diam-diam membiarkan anggota lain terpapar."},
{"id":"TKP-5105", "q":"Pengurus koperasi pegawai mengusulkan dana koperasi dipakai membiayai 'pesantren kilat' yang ternyata dikelola jaringan ekstrem. Sikap Anda sebagai anggota koperasi?", "opts":[{"t":"Menolak usulan itu dalam rapat anggota dan melaporkan indikasi jaringan ekstrem ke pengawas serta aparat.","s":5},{"t":"Menolak usulan itu dalam rapat anggota.","s":4},{"t":"Abstain agar tidak ribut.","s":3},{"t":"Setuju saja karena untuk kegiatan keagamaan.","s":2},{"t":"Mendukung dan menawarkan diri jadi panitia.","s":1}], "ex":"Dana koperasi tidak boleh mengalir ke jaringan ekstrem; anggota wajib menolak lewat forum resmi dan melaporkan indikasinya."},
{"id":"TKP-5106", "q":"Sebuah yayasan menawarkan program 'pembinaan karakter' gratis ke sekolah tempat Anda mengajar, tetapi kurikulumnya mengandung doktrin intoleran dan anti-Pancasila. Sikap Anda sebagai guru?", "opts":[{"t":"Menolak program itu dan melaporkannya ke kepala sekolah serta dinas pendidikan.","s":5},{"t":"Menolak program itu dengan alasan kurikulum tidak sesuai.","s":4},{"t":"Membiarkan sekolah lain yang memutuskan.","s":3},{"t":"Menerimanya karena gratis dan meringankan beban.","s":2},{"t":"Merekomendasikannya ke sekolah-sekolah lain.","s":1}], "ex":"Program pembinaan berdoktrin intoleran adalah infiltrasi ke dunia pendidikan yang wajib ditolak dan dilaporkan, bukan diterima karena gratis."},
{"id":"TKP-5107", "q":"Di kompleks perumahan Anda, sekelompok warga membentuk 'satgas moral' yang sweeping dan mengintimidasi warga berbeda keyakinan dengan dalih ekstrem. Sikap Anda?", "opts":[{"t":"Menolak bergabung, mengajak warga lain menolak, dan melaporkan ke RT/RW serta kepolisian.","s":5},{"t":"Menolak bergabung dan melaporkan ke RT/RW.","s":4},{"t":"Diam saja karena takut jadi sasaran.","s":3},{"t":"Ikut sekali agar dianggap solid.","s":2},{"t":"Bergabung aktif karena merasa aksinya benar.","s":1}], "ex":"Satgas moral yang mengintimidasi atas nama agama adalah premanisme berkedok ekstremisme yang wajib ditolak dan dilaporkan ke aparat."},
{"id":"TKP-5108", "q":"Organisasi profesi tempat Anda terdaftar mengundang penceramah yang dikenal menyebarkan paham khilafah untuk mengisi seminar. Sikap Anda sebagai anggota?", "opts":[{"t":"Memprotes ke pengurus, meminta pembicara diganti, dan melaporkan bila pengurus memaksakan.","s":5},{"t":"Memprotes ke pengurus dan meminta pembicara diganti.","s":4},{"t":"Tidak hadir pada seminar itu.","s":3},{"t":"Hadir saja karena butuh sertifikatnya.","s":2},{"t":"Hadir dan memuji materinya di media sosial.","s":1}], "ex":"Organisasi profesi tidak boleh menjadi panggung propaganda khilafah; anggota wajib memprotes lewat mekanisme organisasi dan melapor bila diabaikan."},
{"id":"TKP-5109", "q":"Kelompok tani di desa Anda disusupi oknum yang mengajak anggotanya menolak program pemerintah dengan dalih 'thaghut' dan menawarkan 'sistem khilafah'. Sikap Anda sebagai penyuluh pertanian?", "opts":[{"t":"Meluruskan ke anggota kelompok tani dan melaporkan oknum itu ke aparat serta pimpinan dinas.","s":5},{"t":"Meluruskan ke anggota kelompok tani agar tidak terpengaruh.","s":4},{"t":"Fokus pada materi pertanian saja tanpa menanggapi.","s":3},{"t":"Membiarkannya karena bukan bidang tugas Anda.","s":2},{"t":"Ikut mendengarkan ceramahnya karena penasaran.","s":1}], "ex":"Penyuluh adalah garda depan negara di desa; propaganda anti-pemerintah berkedok agama di kelompok tani wajib diluruskan dan dilaporkan."},
{"id":"TKP-5110", "q":"Sebuah ormas keagamaan besar di kota Anda terbelah: faksi kecilnya menyebarkan paham ekstrem dan mengkafirkan faksi lain. Sikap Anda sebagai anggota biasa?", "opts":[{"t":"Berpihak pada faksi yang setia pada Pancasila, menolak takfirisme, dan melaporkan faksi ekstrem ke aparat.","s":5},{"t":"Berpihak pada faksi yang setia pada Pancasila dan menjauhi faksi ekstrem.","s":4},{"t":"Netral dan tidak memihak siapa pun.","s":3},{"t":"Ikut faksi ekstrem karena ceramahnya lebih 'tegas'.","s":2},{"t":"Menyebarkan fitnah untuk memperkeruh perpecahan.","s":1}], "ex":"Perpecahan ormas yang disusupi takfirisme menuntut keberpihakan jelas pada Pancasila plus laporan aparat; netralitas dalam menghadapi ekstremisme adalah pembiaran."},
{"id":"TKP-5111", "q":"Komunitas pecinta alam tempat Anda aktif diajak 'jambore' yang ternyata berisi baiat dan doktrin perjuangan bersenjata kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Menolak ikut, memperingatkan anggota lain, dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menolak ikut dan memperingatkan anggota lain.","s":4},{"t":"Ikut jamborenya tetapi menolak baiatnya.","s":3},{"t":"Ikut saja karena acaranya di alam bebas.","s":2},{"t":"Ikut baiat agar diterima komunitas.","s":1}], "ex":"Jambore berkedok hobi yang berujung baiat ekstrem adalah jebakan rekrutmen; wajib ditolak total dan dilaporkan, bukan dihadiri sebagian."},
{"id":"TKP-5112", "q":"Paguyuban pedagang pasar tempat ibu Anda berjualan dimasuki pengurus baru yang mewajibkan iuran 'perjuangan khilafah'. Sikap Anda menasihati ibu?", "opts":[{"t":"Menasihati ibu menolak iuran itu dan melaporkannya ke pengelola pasar serta aparat.","s":5},{"t":"Menasihati ibu menolak iuran itu.","s":4},{"t":"Membayar iurannya agar ibu tidak dikucilkan.","s":3},{"t":"Membiarkan ibu memutuskan sendiri.","s":2},{"t":"Ikut membayar iuran sukarela tambahan.","s":1}], "ex":"Pungutan berkedok perjuangan khilafah di paguyuban adalah pemerasan ideologis; wajib ditolak dan dilaporkan, bukan dibayar demi kenyamanan."},
{"id":"TKP-5113", "q":"Sebuah klub olahraga bela diri merekrut anggotanya untuk 'latihan jihad' dengan doktrin ekstrem anti-NKRI. Adik Anda diajak bergabung. Sikap Anda?", "opts":[{"t":"Melarang adik bergabung, menjelaskan bahayanya, dan melaporkan klub itu ke aparat.","s":5},{"t":"Melarang adik bergabung dan menjelaskan bahayanya.","s":4},{"t":"Membiarkan adik memutuskan sendiri.","s":3},{"t":"Mengizinkan karena melatih fisik itu baik.","s":2},{"t":"Ikut mendaftarkan adik karena biayanya murah.","s":1}], "ex":"Klub bela diri berkedok latihan jihad adalah jalur rekrutmen kombatan ekstrem; keluarga wajib melarang dan negara wajib menindak lewat laporan."},
{"id":"TKP-5114", "q":"Forum warga perumahan Anda didominasi segelintir orang yang memaksakan aturan berpakaian syar'i dengan dalih ekstrem dan mengintimidasi yang menolak. Sikap Anda?", "opts":[{"t":"Menolak pemaksaan itu, menggalang warga yang keberatan, dan melaporkan intimidasi ke aparat.","s":5},{"t":"Menolak pemaksaan itu dalam forum warga.","s":4},{"t":"Mengikuti aturan itu agar aman.","s":3},{"t":"Pindah rumah diam-diam.","s":2},{"t":"Ikut menegakkan aturan itu ke warga lain.","s":1}], "ex":"Pemaksaan aturan berpakaian disertai intimidasi adalah ekstremisme di tingkat komunitas yang wajib dilawan kolektif dan dilaporkan."},
{"id":"TKP-5115", "q":"Sebuah sanggar seni budaya menerima hibah besar dari donatur yang mensyaratkan pementasannya menyisipkan propaganda anti-Pancasila yang ekstrem. Sikap Anda sebagai pengurus sanggar?", "opts":[{"t":"Menolak hibah itu dan melaporkan donatur tersebut ke aparat.","s":5},{"t":"Menolak hibah itu karena syaratnya merusak independensi seni.","s":4},{"t":"Menerima hibah tetapi mengabaikan syaratnya.","s":3},{"t":"Menerima dan memenuhi syaratnya sebagian.","s":2},{"t":"Menerima penuh dan menyesuaikan pementasan.","s":1}], "ex":"Hibah bersyarat propaganda anti-Pancasila adalah pembelian ideologi; seniman berintegritas wajib menolak dan melaporkan donaturnya."},
{"id":"TKP-5116", "q":"Kelompok arisan ibu-ibu di lingkungan Anda disusupi anggota yang rutin menyelipkan ceramah intoleran dan ajakan mendukung khilafah. Sikap Anda sebagai peserta arisan?", "opts":[{"t":"Menegur anggota itu, mengusulkan ke ketua arisan agar dihentikan, dan melaporkan bila terus berlanjut.","s":5},{"t":"Menegur anggota itu agar arisan kembali murni silaturahmi.","s":4},{"t":"Keluar dari arisan tanpa penjelasan.","s":3},{"t":"Tetap ikut karena butuh arisannya.","s":2},{"t":"Ikut menyimak dan membenarkan ceramahnya.","s":1}], "ex":"Arisan yang disusupi propaganda khilafah harus dibersihkan lewat teguran dan mekanisme kelompok; keluar diam-diam membiarkan ibu-ibu lain terpapar."},
{"id":"TKP-5117", "q":"Organisasi mahasiswa di kampus Anda dikuasai kelompok yang mewajibkan kadernya menolak hormat bendera sebagai 'bukti tauhid' yang ekstrem. Sikap Anda sebagai mahasiswa biasa?", "opts":[{"t":"Menolak doktrin itu, menggalang mahasiswa lain, dan melaporkan ke rektorat serta aparat.","s":5},{"t":"Menolak doktrin itu dan tidak bergabung dengan kelompoknya.","s":4},{"t":"Menghindar dari organisasi itu tanpa bersuara.","s":3},{"t":"Bergabung karena jaringannya luas.","s":2},{"t":"Ikut menyebarkan doktrinnya ke organisasi lain.","s":1}], "ex":"Penolakan hormat bendera berkedok tauhid adalah indoktrinasi ekstrem di kampus yang wajib dilawan kolektif dan dilaporkan ke rektorat."},
{"id":"TKP-5118", "q":"Sebuah komunitas ojek online dibentuk 'korlap' yang mengarahkan anggotanya ikut aksi-aksi kelompok ekstrem dengan iming-iming order prioritas. Sikap Anda sebagai anggota?", "opts":[{"t":"Menolak arahan itu dan melaporkan korlapnya ke aplikator serta aparat.","s":5},{"t":"Menolak arahan itu dan keluar dari komunitasnya.","s":4},{"t":"Ikut sekali agar dapat order prioritas.","s":3},{"t":"Ikut rutin karena menguntungkan.","s":2},{"t":"Menjadi koordinator aksi di wilayah Anda.","s":1}], "ex":"Mobilisasi massa berkedok komunitas profesi untuk aksi ekstrem adalah eksploitasi ekonomi; wajib ditolak dan korlapnya dilaporkan."},
{"id":"TKP-5119", "q":"Yayasan panti asuhan tempat Anda menjadi donatur diketahui menanamkan doktrin kebencian dan paham ekstrem ke anak-anak asuhnya. Sikap Anda?", "opts":[{"t":"Menghentikan donasi, melaporkan yayasan itu ke dinas sosial dan aparat, serta memastikan anak-anak mendapat pembinaan yang benar.","s":5},{"t":"Menghentikan donasi dan melaporkan yayasan itu ke dinas sosial.","s":4},{"t":"Menghentikan donasi diam-diam.","s":3},{"t":"Tetap berdonasi karena kasihan anak-anaknya.","s":2},{"t":"Menambah donasi agar anak-anak 'terurus'.","s":1}], "ex":"Panti asuhan penanam doktrin kebencian adalah kejahatan terhadap anak yang wajib dilaporkan; donasi yang terus mengalir justru membiayai radikalisasi."},
{"id":"TKP-5120", "q":"Kelompok suporter bola yang Anda ikuti diajak 'tandang' yang ternyata aksi sweeping rumah ibadah kelompok minoritas dengan dalih intoleran. Sikap Anda?", "opts":[{"t":"Menolak ikut, memperingatkan suporter lain, dan melaporkan koordinatornya ke aparat.","s":5},{"t":"Menolak ikut dan tidak menghadiri aksinya.","s":4},{"t":"Ikut tandang tetapi tidak ikut sweeping.","s":3},{"t":"Ikut karena solidaritas suporter.","s":2},{"t":"Ikut dan merekam aksinya untuk disebar.","s":1}], "ex":"Aksi sweeping rumah ibadah berkedok tandang suporter adalah kekerasan intoleran yang wajib ditolak dan dilaporkan; solidaritas tidak berlaku untuk kejahatan."},
{"id":"TKP-5121", "q":"Sebuah majelis taklim besar di kota Anda diambil alih pengurus baru yang mengganti materi dengan doktrin khilafah dan permusuhan terhadap pemerintah. Sikap Anda sebagai jamaah lama?", "opts":[{"t":"Memprotes dalam forum jamaah, menggalang jamaah lama, dan melaporkan pengurus baru ke aparat.","s":5},{"t":"Memprotes dan pindah ke majelis taklim lain.","s":4},{"t":"Tetap hadir karena sudah terbiasa.","s":3},{"t":"Mengikuti materi barunya karena penceramahnya karismatik.","s":2},{"t":"Membantu pengurus baru menyebarkan materinya.","s":1}], "ex":"Pengambilalihan majelis taklim untuk propaganda khilafah harus dilawan jamaah lewat protes dan laporan; kepasifan sama dengan menyerahkan mimbar ke ekstremis."},
{"id":"TKP-5122", "q":"Komunitas gamer yang Anda ikuti memiliki kanal khusus berisi rekrutmen 'jihad digital' kelompok ekstrem dengan bahasa gaul. Sikap Anda?", "opts":[{"t":"Keluar dari kanal itu, melaporkan ke admin platform dan aparat siber.","s":5},{"t":"Keluar dari kanal itu dan memperingatkan teman-teman gamer.","s":4},{"t":"Tetap di kanal untuk 'seru-seruan' tanpa ikut.","s":3},{"t":"Ikut nimbrung karena bahasanya lucu.","s":2},{"t":"Ikut menyebarkan tautan kanal itu.","s":1}], "ex":"Rekrutmen ekstrem berkedok konten gaul menyasar gamer muda; kanal seperti itu wajib dilaporkan ke platform dan aparat siber."},
{"id":"TKP-5123", "q":"Sebuah koperasi simpan pinjam syariah menawarkan 'investasi perjuangan' yang dananya disalurkan ke jaringan ekstrem. Sikap Anda sebagai nasabah?", "opts":[{"t":"Menolak berinvestasi, menarik dana Anda, dan melaporkan koperasi itu ke OJK serta aparat.","s":5},{"t":"Menolak berinvestasi dan menarik dana Anda.","s":4},{"t":"Tetap menjadi nasabah untuk produk lainnya.","s":3},{"t":"Ikut berinvestasi karena imbal hasilnya tinggi.","s":2},{"t":"Mengajak kerabat ikut berinvestasi.","s":1}], "ex":"Investasi yang dananya mengalir ke jaringan ekstrem adalah pendanaan terorisme; nasabah wajib menarik dana dan melaporkannya ke OJK dan aparat."},
{"id":"TKP-5124", "q":"Kelompok relawan bencana yang Anda ikuti disusupi oknum yang menyeleksi korban bantuan berdasarkan kesamaan paham ekstremnya. Sikap Anda sebagai relawan?", "opts":[{"t":"Memprotes seleksi diskriminatif itu, melaporkannya ke koordinator relawan dan aparat.","s":5},{"t":"Memprotes dan memastikan bantuan disalurkan adil.","s":4},{"t":"Fokus menyalurkan bantuan sendiri tanpa memprotes.","s":3},{"t":"Mengikuti seleksinya agar tidak ribut.","s":2},{"t":"Ikut menyeleksi karena 'seiman lebih utama'.","s":1}], "ex":"Diskriminasi korban bencana berbasis paham ekstrem adalah kejahatan kemanusiaan; relawan wajib memprotes dan melaporkan, bukan mengikutinya."},
{"id":"TKP-5125", "q":"Sebuah sanggar tahfidz menawarkan beasiswa penuh ke luar negeri bagi santrinya, tetapi kurikulum lanjutannya bermuatan doktrin terorisme. Anak tetangga Anda berminat. Sikap Anda?", "opts":[{"t":"Memperingatkan tetangga tentang indikasi doktrinnya dan melaporkan sanggar itu ke Kemenag serta aparat.","s":5},{"t":"Memperingatkan tetangga agar membatalkan niatnya.","s":4},{"t":"Membiarkan karena itu urusan keluarga tetangga.","s":3},{"t":"Ikut mendorong karena beasiswanya menggiurkan.","s":2},{"t":"Mendaftarkan anak Anda juga.","s":1}], "ex":"Beasiswa tahfidz berkurikulum doktrin terorisme adalah jalur rekrutmen lintas negara; wajib diperingatkan dan dilaporkan ke Kemenag dan aparat."}
,
{"id":"TKP-5126", "q":"Sebuah kanal podcast populer yang Anda dengarkan perlahan menyelipkan episode-episode berisi doktrin ekstrem dan ajakan menolak Pancasila. Sikap Anda sebagai pendengar setia?", "opts":[{"t":"Berhenti mendengarkan, melaporkan kanal itu ke platform dan aparat, serta memperingatkan teman yang juga mendengarkan.","s":5},{"t":"Berhenti mendengarkan dan memperingatkan teman-teman.","s":4},{"t":"Tetap mendengarkan episode non-politiknya saja.","s":3},{"t":"Tetap mendengarkan semua episodenya karena host-nya karismatik.","s":2},{"t":"Membagikan episode doktrinnya ke media sosial.","s":1}], "ex":"Podcast yang menyusupkan doktrin ekstrem adalah propaganda sistematis yang wajib dilaporkan ke platform dan aparat, bukan sekadar dihindari."},
{"id":"TKP-5127", "q":"Seorang streamer gim favorit Anda mulai menyisipkan ceramah intoleran dan ajakan mendukung khilafah di sela siaran langsungnya. Sikap Anda sebagai penonton?", "opts":[{"t":"Berhenti menonton, melaporkan akunnya ke platform, dan memperingatkan komunitas penonton.","s":5},{"t":"Berhenti menonton dan melaporkan akunnya ke platform.","s":4},{"t":"Tetap menonton tetapi mengabaikan ceramahnya.","s":3},{"t":"Tetap menonton karena permainannya seru.","s":2},{"t":"Ikut menyebarkan potongan ceramahnya.","s":1}], "ex":"Streamer yang menyisipkan propaganda khilafah mengeksploitasi basis penggemarnya; wajib dilaporkan ke platform agar ditindak."},
{"id":"TKP-5128", "q":"Teman Anda menjadi admin kanal streaming dakwah yang ternyata menyiarkan kajian-kajian bermuatan terorisme. Ia mengajak Anda menjadi moderator. Sikap Anda?", "opts":[{"t":"Menolak tegas dan melaporkan kanal itu ke platform serta aparat penegak hukum.","s":5},{"t":"Menolak ajakannya dan menjauhinya.","s":4},{"t":"Menerima tetapi hanya memoderasi komentar.","s":3},{"t":"Menerima karena dijanjikan bayaran.","s":2},{"t":"Menerima dan ikut mempromosikan kanalnya.","s":1}], "ex":"Menjadi moderator kanal propaganda terorisme sama dengan ikut memfasilitasi kejahatan; wajib ditolak dan dilaporkan."},
{"id":"TKP-5129", "q":"Sebuah serial web fiktif yang viral ternyata memuat subliminal glorifikasi aksi terorisme dan kebencian intoleran. Anak remaja Anda menontonnya. Sikap Anda sebagai orang tua?", "opts":[{"t":"Melarang anak menonton, menjelaskan bahayanya, dan melaporkan serial itu ke KPI serta aparat.","s":5},{"t":"Melarang anak menonton dan menjelaskan bahayanya.","s":4},{"t":"Membiarkannya karena 'hanya fiksi'.","s":3},{"t":"Ikut menonton karena ceritanya seru.","s":2},{"t":"Merekomendasikannya ke orang tua lain.","s":1}], "ex":"Glorifikasi terorisme dalam konten fiksi adalah radikalisasi terselubung yang menarget remaja; orang tua wajib melarang dan melaporkannya."},
{"id":"TKP-5130", "q":"Influencer dengan jutaan pengikut yang Anda follow mulai mengunggah konten 'dakwah' berisi ujaran intoleran terhadap kelompok minoritas. Sikap Anda?", "opts":[{"t":"Unfollow, melaporkan kontennya, dan mengedukasi pengikut Anda agar tidak terpengaruh.","s":5},{"t":"Unfollow dan melaporkan kontennya ke platform.","s":4},{"t":"Tetap follow tetapi tidak menonton kontennya.","s":3},{"t":"Tetap follow karena konten lainnya bermanfaat.","s":2},{"t":"Ikut membagikan konten intolerannya.","s":1}], "ex":"Influencer penyebar ujaran intoleran memanfaatkan jangkauannya untuk radikalisasi; wajib di-unfollow dan dilaporkan."},
{"id":"TKP-5131", "q":"Sebuah aplikasi 'kajian interaktif' yang diunduh rekan Anda ternyata berisi kuis-kuis yang jawabannya mengarah pada doktrin ekstrem. Sikap Anda setelah mengetahuinya?", "opts":[{"t":"Menasihati rekan menghapus aplikasinya dan melaporkan aplikasi itu ke platform serta aparat.","s":5},{"t":"Menasihati rekan menghapus aplikasinya.","s":4},{"t":"Membiarkannya karena rekan sudah dewasa.","s":3},{"t":"Ikut mengunduh karena penasaran.","s":2},{"t":"Memberi ulasan bintang lima agar makin populer.","s":1}], "ex":"Aplikasi kajian berdoktrin ekstrem adalah alat radikalisasi digital yang wajib dilaporkan agar diturunkan dari platform."},
{"id":"TKP-5132", "q":"Di platform video pendek, algoritma terus menyodorkan konten ceramah ekstrem ke beranda Anda setelah sekali menonton. Sikap Anda?", "opts":[{"t":"Memblokir dan melaporkan setiap konten ekstrem itu agar algoritma berhenti menyodorkannya.","s":5},{"t":"Memblokir akun-akun penyebar konten ekstrem.","s":4},{"t":"Mengabaikannya dan scroll lewat.","s":3},{"t":"Menontonnya karena algoritma 'tahu yang saya suka'.","s":2},{"t":"Menyukai dan membagikannya agar makin viral.","s":1}], "ex":"Algoritma yang menyodorkan konten ekstrem harus dilawan dengan blokir dan laporan massal; keterlibatan pasif justru melatih algoritma menyebarluaskan propaganda."},
{"id":"TKP-5133", "q":"Sebuah webinar 'literasi keagamaan' gratis yang diikuti rekan Anda ternyata diisi pemateri yang mengajarkan paham khilafah. Sikap Anda menasihati rekan?", "opts":[{"t":"Menasihati rekan keluar dari webinar itu dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menasihati rekan keluar dari webinar itu.","s":4},{"t":"Membiarkan karena gratis dan menambah wawasan.","s":3},{"t":"Ikut mendaftar karena penasaran materinya.","s":2},{"t":"Ikut mendaftar dan mengajak teman lain.","s":1}], "ex":"Webinar gratis bermateri khilafah adalah umpan rekrutmen; peserta wajib keluar dan penyelenggaranya dilaporkan."},
{"id":"TKP-5134", "q":"Teman Anda dibayar menjadi buzzer untuk menyebarkan konten provokatif bernada ekstrem menjelang pemilu. Ia mengajak Anda bergabung karena bayarannya besar. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran itu ke Bawaslu serta aparat karena provokasi ekstrem merusak demokrasi.","s":5},{"t":"Menolak karena tidak ingin terlibat.","s":4},{"t":"Mempertimbangkan karena butuh uang.","s":3},{"t":"Bergabung tetapi hanya menyebar yang 'ringan'.","s":2},{"t":"Bergabung penuh demi bayaran besar.","s":1}], "ex":"Menjadi buzzer provokasi ekstrem adalah kejahatan pemilu sekaligus penyebaran paham radikal; wajib ditolak dan dilaporkan ke Bawaslu."},
{"id":"TKP-5135", "q":"Sebuah stasiun radio komunitas menyiarkan ceramah rutin yang isinya hasutan intoleran terhadap kelompok agama lain. Sikap Anda sebagai pendengar warga setempat?", "opts":[{"t":"Melaporkan siaran itu ke KPI dan aparat, serta mengajak warga lain memprotes.","s":5},{"t":"Melaporkan siaran itu ke KPI.","s":4},{"t":"Pindah ke stasiun radio lain.","s":3},{"t":"Tetap mendengarkan karena penyiarnya lucu.","s":2},{"t":"Menjadi pendengar setia dan donatur stasiun itu.","s":1}], "ex":"Radio komunitas penyebar hasutan intoleran melanggar UU Penyiaran dan wajib dilaporkan ke KPI; pindah kanal tanpa laporan membiarkan hasutan berlanjut."},
{"id":"TKP-5136", "q":"Grup diskusi film daring yang Anda ikuti tiba-tiba dipenuhi anggota baru yang memutar diskusi ke propaganda terorisme. Sikap Anda?", "opts":[{"t":"Melaporkan anggota-anggota itu ke admin grup dan aparat bila mereka menyebar materi terorisme.","s":5},{"t":"Melaporkan ke admin grup agar mereka dikeluarkan.","s":4},{"t":"Keluar dari grup tanpa laporan.","s":3},{"t":"Tetap di grup karena topik filmnya menarik.","s":2},{"t":"Ikut berdiskusi tentang 'perjuangan' mereka.","s":1}], "ex":"Penyusupan propaganda terorisme ke grup hobi adalah taktik rekrutmen yang wajib dilaporkan; keluar tanpa laporan membiarkan anggota lain terpapar."},
{"id":"TKP-5137", "q":"Seorang YouTuber 'eks radikal' membuat konten testimoni yang ternyata justru mengagungkan aksi terorisme masa lalunya. Sikap Anda sebagai penonton?", "opts":[{"t":"Melaporkan kontennya sebagai glorifikasi terorisme dan mengedukasi penonton lain di kolom komentar.","s":5},{"t":"Melaporkan kontennya ke platform.","s":4},{"t":"Menganggapnya sekadar cerita masa lalu.","s":3},{"t":"Mengaguminya karena 'pengalamannya luar biasa'.","s":2},{"t":"Membagikan videonya sebagai 'inspirasi'.","s":1}], "ex":"Testimoni yang mengagungkan terorisme adalah glorifikasi berkedok tobat; wajib dilaporkan agar tidak menjadi inspirasi radikalisasi."},
{"id":"TKP-5138", "q":"Aplikasi pesan instan menawarkan 'bot dakwah otomatis' ke grup kantor Anda; bot itu ternyata menyebarkan pesan-pesan intoleran tiap hari. Sikap Anda sebagai admin grup?", "opts":[{"t":"Mengeluarkan bot itu dari grup dan melaporkan pembuatnya ke platform serta aparat.","s":5},{"t":"Mengeluarkan bot itu dari grup.","s":4},{"t":"Membiarkannya karena pesannya kadang 'bagus'.","s":3},{"t":"Menambahkannya ke grup-grup lain.","s":2},{"t":"Menghubungi pembuatnya untuk versi premium.","s":1}], "ex":"Bot penyebar pesan intoleran adalah propaganda otomatis yang wajib dikeluarkan dan dilaporkan pembuatnya."},
{"id":"TKP-5139", "q":"Sebuah platform donasi daring menampung penggalangan dana 'kemanusiaan' yang ternyata disalurkan ke kelompok ekstrem. Teman Anda berdonasi di sana. Sikap Anda?", "opts":[{"t":"Memperingatkan teman, memintanya menarik donasi, dan melaporkan platform itu ke aparat.","s":5},{"t":"Memperingatkan teman agar tidak berdonasi lagi.","s":4},{"t":"Membiarkannya karena niat teman baik.","s":3},{"t":"Ikut berdonasi karena untuk kemanusiaan.","s":2},{"t":"Membantu mempromosikan penggalangan dananya.","s":1}], "ex":"Donasi kemanusiaan yang disalurkan ke kelompok ekstrem adalah pendanaan terorisme; wajib diperingatkan dan dilaporkan."},
{"id":"TKP-5140", "q":"Dalam gim daring yang dimainkan keponakan Anda, pemain lain mengajaknya bergabung ke 'klan' yang ternyata forum rekrutmen ekstrem. Sikap Anda sebagai pamannya?", "opts":[{"t":"Melarang keponakan bergabung, menjelaskan bahayanya, dan melaporkan klan itu ke pengembang gim serta aparat.","s":5},{"t":"Melarang keponakan bergabung dan menjelaskan bahayanya.","s":4},{"t":"Menganggapnya hanya permainan.","s":3},{"t":"Membiarkan karena keponakan butuh teman main.","s":2},{"t":"Ikut membuat akun untuk bergabung ke klannya.","s":1}], "ex":"Rekrutmen ekstrem lewat gim daring menarget anak-anak; keluarga wajib melarang dan melaporkan klan itu ke pengembang dan aparat."},
{"id":"TKP-5141", "q":"Sebuah kanal berita daring alternatif rutin memuat artikel yang membenarkan aksi terorisme sebagai 'perlawanan sah'. Sikap Anda sebagai pembaca?", "opts":[{"t":"Berhenti membaca, melaporkan medianya ke Dewan Pers dan aparat.","s":5},{"t":"Berhenti membaca media itu.","s":4},{"t":"Tetap membaca sebagai pembanding.","s":3},{"t":"Membagikan artikelnya karena 'sudut pandang berbeda'.","s":2},{"t":"Menjadi kontributor penulis di media itu.","s":1}], "ex":"Media yang membenarkan terorisme adalah corong propaganda ekstrem yang wajib dilaporkan ke Dewan Pers dan aparat."},
{"id":"TKP-5142", "q":"Teman sekantor Anda kecanduan menonton ceramah ekstrem di platform video dan mulai menunjukkan perubahan sikap intoleran. Sikap Anda sebagai rekan?", "opts":[{"t":"Menasihatinya dengan empati, mengajak diskusi sehat, dan melaporkan ke atasan bila ia mulai menyebarkan pahamnya di kantor.","s":5},{"t":"Menasihatinya dengan empati dan mengajak diskusi sehat.","s":4},{"t":"Menjauhinya agar tidak tertular.","s":3},{"t":"Membiarkannya karena itu pilihannya.","s":2},{"t":"Ikut menonton ceramah yang ia tonton.","s":1}], "ex":"Rekan yang terpapar konten ekstrem butuh nasihat empatik dan intervensi; bila ia menyebarkan di kantor, wajib dilaporkan ke atasan."},
{"id":"TKP-5143", "q":"Sebuah e-book gratis 'panduan hijrah' yang viral ternyata bab akhirnya berisi manual pembuatan propaganda terorisme. Sikap Anda setelah mengetahuinya?", "opts":[{"t":"Menghapus e-book itu dan melaporkan penyebarnya ke platform serta aparat.","s":5},{"t":"Menghapus e-book itu dari perangkat Anda.","s":4},{"t":"Menyimpannya tetapi tidak membaca bab akhirnya.","s":3},{"t":"Membacanya sampai habis karena penasaran.","s":2},{"t":"Menyebarkannya ke grup-grup Anda.","s":1}], "ex":"E-book berisi manual propaganda terorisme adalah materi terlarang yang wajib dihapus dan dilaporkan penyebarnya."},
{"id":"TKP-5144", "q":"Dalam siaran langsung amal, seorang donatur besar mensyaratkan MC membacakan pesan dukungan untuk 'perjuangan khilafah'. Sikap Anda sebagai panitia siaran?", "opts":[{"t":"Menolak syarat itu secara tegas dan menghentikan kerja sama dengan donatur tersebut.","s":5},{"t":"Menolak syarat itu dengan alasan tidak sesuai tema amal.","s":4},{"t":"Membacakan pesannya agar donasi tetap cair.","s":3},{"t":"Membacakan plus menambahkan dukungan pribadi.","s":2},{"t":"Mengundangnya menjadi donatur tetap acara.","s":1}], "ex":"Donasi bersyarat propaganda khilafah adalah pembelian panggung dakwah ekstrem; panitia wajib menolak meski donasinya besar."},
{"id":"TKP-5145", "q":"Sebuah forum daring luar negeri merekrut moderator berbahasa Indonesia untuk kanal-kanal propaganda ekstremnya dengan bayaran dolar. Teman Anda tertarik melamar. Sikap Anda?", "opts":[{"t":"Melarangnya dengan tegas, menjelaskan itu kejahatan terorisme, dan melaporkannya ke aparat.","s":5},{"t":"Melarangnya dengan tegas dan menjelaskan risikonya.","s":4},{"t":"Membiarkannya karena butuh penghasilan.","s":3},{"t":"Ikut melamar karena bayarannya menggiurkan.","s":2},{"t":"Membantu teman membuat lamaran yang meyakinkan.","s":1}], "ex":"Menjadi moderator propaganda ekstrem asing adalah keterlibatan dalam terorisme lintas negara; wajib dilarang dan dilaporkan."},
{"id":"TKP-5146", "q":"Konten 'prank' di media sosial yang viral ternyata berisi ujaran kebencian intoleran terhadap kelompok minoritas. Adik Anda menirunya. Sikap Anda?", "opts":[{"t":"Melarang adik meniru, menjelaskan bahayanya, dan melaporkan konten itu ke platform.","s":5},{"t":"Melarang adik meniru dan menjelaskan bahayanya.","s":4},{"t":"Menertawakannya karena 'hanya prank'.","s":3},{"t":"Ikut menonton karena viral.","s":2},{"t":"Membantu adik membuat prank serupa.","s":1}], "ex":"Prank berujaran kebencian menormalisasi intoleransi di kalangan muda; wajib dilarang dan kontennya dilaporkan."},
{"id":"TKP-5147", "q":"Sebuah stasiun televisi swasta menayangkan sinetron yang tokoh antagonisnya digambarkan persis sebagai stereotip kelompok agama minoritas yang intoleran. Sikap Anda sebagai penonton?", "opts":[{"t":"Melaporkan tayangan itu ke KPI sebagai konten yang menyuburkan intoleransi.","s":5},{"t":"Mengkritiknya di media sosial dengan argumen yang sehat.","s":4},{"t":"Tetap menonton karena ceritanya seru.","s":3},{"t":"Menganggapnya wajar sebagai dramatisasi.","s":2},{"t":"Memuji sinetronnya sebagai 'realistis'.","s":1}], "ex":"Stereotip intoleran di tayangan televisi menyuburkan prasangka massal; penonton kritis wajib melaporkannya ke KPI."},
{"id":"TKP-5148", "q":"Teman Anda membuat filter media sosial bertuliskan dukungan untuk organisasi teroris sebagai 'ekspresi kebebasan'. Ia meminta Anda memakainya. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan filter itu ke platform sebagai dukungan terhadap terorisme.","s":5},{"t":"Menolak memakainya.","s":4},{"t":"Mengabaikan permintaannya.","s":3},{"t":"Memakainya sekali untuk seru-seruan.","s":2},{"t":"Memakai dan menantang teman lain ikut.","s":1}], "ex":"Filter dukungan untuk organisasi teroris bukan kebebasan berekspresi melainkan propaganda; wajib ditolak dan dilaporkan."},
{"id":"TKP-5149", "q":"Sebuah layanan streaming musik memuat playlist 'nasheed perjuangan' yang liriknya mengagungkan aksi terorisme. Sikap Anda sebagai pengguna?", "opts":[{"t":"Melaporkan playlist itu ke platform sebagai konten pro-terorisme.","s":5},{"t":"Berhenti mendengarkan playlist itu.","s":4},{"t":"Tetap mendengarkan karena melodinya enak.","s":3},{"t":"Membagikannya ke teman-teman.","s":2},{"t":"Membuat playlist serupa yang lebih lengkap.","s":1}], "ex":"Konten musik pengagung terorisme adalah propaganda yang wajib dilaporkan ke platform agar diturunkan."},
{"id":"TKP-5150", "q":"Dalam grup alumni sekolah, seorang anggota rutin membagikan tautan 'kajian online' yang isinya doktrin ekstrem anti-NKRI. Sikap Anda sebagai anggota grup?", "opts":[{"t":"Memprotes di grup, meminta admin menertibkan, dan melaporkan bila ia terus menyebar.","s":5},{"t":"Memprotes di grup dan meminta admin menertibkan.","s":4},{"t":"Mengabaikan tautannya.","s":3},{"t":"Mengklik tautannya karena penasaran.","s":2},{"t":"Ikut membagikan tautan itu ke grup lain.","s":1}], "ex":"Grup alumni bukan tempat propaganda anti-NKRI; anggota wajib memprotes, admin wajib menertibkan, dan pelakunya dilaporkan bila membandel."}
,
{"id":"TKP-5151", "q":"Anak Anda yang masih SD pulang membawa selebaran komik bergambar pahlawan 'pejuang khilafah' yang dibagikan orang tak dikenal di depan sekolah. Sikap Anda sebagai orang tua?", "opts":[{"t":"Menyita selebarannya, menjelaskan ke anak bahwa itu propaganda ekstrem, dan melaporkannya ke sekolah serta aparat.","s":5},{"t":"Menyita selebarannya dan menjelaskan ke anak.","s":4},{"t":"Membuang selebarannya tanpa penjelasan.","s":3},{"t":"Membiarkan anak membacanya karena gambarnya menarik.","s":2},{"t":"Menganggapnya bahan bacaan alternatif yang bagus.","s":1}], "ex":"Propaganda ekstrem berkedok komik anak adalah radikalisasi dini yang wajib dilaporkan; anak butuh penjelasan sesuai usianya."},
{"id":"TKP-5152", "q":"Di PAUD tempat anak Anda bersekolah, seorang guru baru mengajarkan lagu-lagu yang liriknya mengandung kebencian intoleran terhadap kelompok lain. Sikap Anda?", "opts":[{"t":"Melaporkan guru itu ke kepala sekolah dan dinas pendidikan agar ditindak.","s":5},{"t":"Memprotes ke kepala sekolah dan meminta guru diganti.","s":4},{"t":"Memindahkan anak ke PAUD lain tanpa protes.","s":3},{"t":"Membiarkannya karena anak belum paham lirik.","s":2},{"t":"Merekam dan menyebarkannya sebagai 'lucu'.","s":1}], "ex":"Penanaman kebencian intoleran sejak PAUD adalah kejahatan terhadap anak yang wajib dilaporkan ke dinas pendidikan."},
{"id":"TKP-5153", "q":"Keponakan remaja Anda mulai mengidolakan tokoh ekstrem dari konten media sosial dan menolak nasihat keluarga dengan dalih 'jihad'. Sikap Anda sebagai pamannya?", "opts":[{"t":"Mengajaknya dialog dengan empati, melibatkan orang tua dan guru, serta melaporkan akun-akun yang mempengaruhinya.","s":5},{"t":"Mengajaknya dialog dengan empati dan melibatkan orang tuanya.","s":4},{"t":"Memarahinya agar berhenti.","s":3},{"t":"Membiarkannya karena fase remaja.","s":2},{"t":"Ikut mengagumi tokoh itu agar dekat dengannya.","s":1}], "ex":"Remaja terpapar ekstrem butuh dialog empatik plus pelibatan keluarga dan sekolah; kemarahan justru mendorongnya makin jauh."},
{"id":"TKP-5154", "q":"Sebuah les privat menawarkan 'kurikulum karakter Islami' yang ternyata menanamkan doktrin anti-Pancasila yang ekstrem ke anak-anak. Tetangga Anda mendaftarkan anaknya. Sikap Anda?", "opts":[{"t":"Memperingatkan tetangga dan melaporkan les itu ke dinas pendidikan serta aparat.","s":5},{"t":"Memperingatkan tetangga agar membatalkan pendaftaran.","s":4},{"t":"Membiarkan karena urusan keluarga tetangga.","s":3},{"t":"Ikut mendaftarkan anak karena biayanya murah.","s":2},{"t":"Merekomendasikannya ke orang tua lain.","s":1}], "ex":"Les berkurikulum doktrin anti-Pancasila adalah radikalisasi anak berkedok pendidikan yang wajib dilaporkan."},
{"id":"TKP-5155", "q":"Anak Anda diajak teman sekelasnya mengikuti 'ekstrakurikuler rahasia' yang ternyata latihan ala militer kelompok ekstrem. Sikap Anda setelah anak bercerita?", "opts":[{"t":"Melarang anak ikut, menenangkan anak, dan segera melaporkan ke sekolah serta aparat.","s":5},{"t":"Melarang anak ikut dan melaporkannya ke sekolah.","s":4},{"t":"Menasihati anak menolak dengan halus.","s":3},{"t":"Mengizinkan sekali untuk pengalaman.","s":2},{"t":"Mengizinkan karena melatih kedisiplinan.","s":1}], "ex":"Ekstrakurikuler rahasia ala militer ekstrem menarget anak sekolah; wajib dilarang dan dilaporkan secepatnya."},
{"id":"TKP-5156", "q":"Sebuah taman bermain anak di mal memutar lagu anak-anak yang liriknya disisipi ajakan intoleran. Sikap Anda sebagai pengunjung yang menyadarinya?", "opts":[{"t":"Melaporkan ke pengelola mal dan aparat agar kontennya diganti.","s":5},{"t":"Memprotes ke pengelola mal.","s":4},{"t":"Mengajak anak pindah ke wahana lain.","s":3},{"t":"Membiarkannya karena anak tidak paham lirik.","s":2},{"t":"Menganggapnya tidak masalah.","s":1}], "ex":"Konten anak yang disisipi ajakan intoleran adalah radikalisasi terselubung di ruang publik yang wajib dilaporkan."},
{"id":"TKP-5157", "q":"Sepupu Anda menikahkan anaknya yang masih di bawah umur dengan anggota kelompok ekstrem sebagai 'jodoh seperjuangan'. Sikap Anda sebagai kerabat?", "opts":[{"t":"Menasihati keluarga agar membatalkan dan melaporkan ke KPAI serta aparat karena perkawinan anak dan eksploitasi ekstrem.","s":5},{"t":"Menasihati keluarga agar membatalkan pernikahan itu.","s":4},{"t":"Tidak menghadiri pernikahannya sebagai protes diam.","s":3},{"t":"Menghadiri karena undangan keluarga.","s":2},{"t":"Mendukung karena 'dijodohkan orang saleh'.","s":1}], "ex":"Perkawinan anak dengan anggota kelompok ekstrem adalah eksploitasi ganda yang wajib dicegah dan dilaporkan ke KPAI."},
{"id":"TKP-5158", "q":"Di lingkungan Anda, seorang 'ustaz cilik' dadakan yang masih remaja menyebarkan ceramah-ceramah intoleran dan provokatif lewat media sosial. Sikap Anda sebagai tokoh masyarakat?", "opts":[{"t":"Mengajak orang tuanya berdialog, memberi pembinaan, dan melaporkan kontennya bila bermuatan ekstrem.","s":5},{"t":"Mengajak orang tuanya berdialog dan memberi pembinaan.","s":4},{"t":"Membiarkannya karena masih anak-anak.","s":3},{"t":"Mengundangnya ceramah karena viral.","s":2},{"t":"Menjadikannya ikon kampanye donasi.","s":1}], "ex":"Anak penceramah intoleran adalah korban eksploitasi yang butuh pembinaan, bukan panggung; orang tua wajib dilibatkan."},
{"id":"TKP-5159", "q":"Anak tetangga Anda direkrut menjadi 'kurir' selebaran propaganda ekstrem dengan iming-iming uang jajan. Sikap Anda setelah mengetahuinya?", "opts":[{"t":"Melaporkan perekrutnya ke aparat dan memperingatkan orang tua anak itu.","s":5},{"t":"Memperingatkan orang tua anak itu.","s":4},{"t":"Menasihati anak itu agar berhenti.","s":3},{"t":"Membiarkannya karena hanya selebaran.","s":2},{"t":"Meminta anak itu membagikan selebaran ke rumah Anda.","s":1}], "ex":"Perekrutan anak sebagai kurir propaganda adalah eksploitasi anak oleh jaringan ekstrem yang wajib dilaporkan ke aparat."},
{"id":"TKP-5160", "q":"Sebuah aplikasi gim edukasi anak yang diunduh anak Anda ternyata level-levelnya berisi misi 'memerangi thaghut' yang ekstrem. Sikap Anda?", "opts":[{"t":"Menghapus gimnya, menjelaskan ke anak, dan melaporkan aplikasi itu ke platform serta aparat.","s":5},{"t":"Menghapus gimnya dan menjelaskan ke anak.","s":4},{"t":"Membatasi waktu mainnya saja.","s":3},{"t":"Membiarkan karena anak senang memainkannya.","s":2},{"t":"Merekomendasikannya ke orang tua lain.","s":1}], "ex":"Gim edukasi bermisi ekstrem adalah radikalisasi interaktif untuk anak yang wajib dilaporkan agar diturunkan."},
{"id":"TKP-5161", "q":"Ibu Anda yang sudah sepuh diajak tetangganya mengikuti pengajian yang ternyata berisi doktrin kebencian intoleran. Sikap Anda sebagai anaknya?", "opts":[{"t":"Menasihati ibu dengan lembut, mengajak ke pengajian yang moderat, dan melaporkan penyelenggaranya.","s":5},{"t":"Menasihati ibu dengan lembut dan mengajak ke pengajian lain.","s":4},{"t":"Melarang ibu keluar rumah.","s":3},{"t":"Membiarkan karena ibu sudah tua.","s":2},{"t":"Ikut mengantar ibu ke pengajian itu.","s":1}], "ex":"Lansia adalah sasaran empuk doktrinasi; keluarga wajib menasihati lembut, mengalihkan ke pengajian moderat, dan melaporkan penyelenggaranya."},
{"id":"TKP-5162", "q":"Ayah Anda mulai membagikan konten-konten provokatif bernada ekstrem di grup keluarga setelah menonton ceramah tertentu. Sikap Anda?", "opts":[{"t":"Menasihatinya dengan hormat, memberikan kontra-narasi yang sejuk, dan melaporkan sumber kontennya bila bermuatan ekstrem.","s":5},{"t":"Menasihatinya dengan hormat dan memberikan kontra-narasi.","s":4},{"t":"Keluar dari grup keluarga.","s":3},{"t":"Membiarkannya karena menghormati orang tua.","s":2},{"t":"Ikut membagikan kontennya agar ayah senang.","s":1}], "ex":"Orang tua terpapar konten ekstrem butuh nasihat hormat plus kontra-narasi; sumber kontennya wajib dilaporkan bila bermuatan ekstrem."},
{"id":"TKP-5163", "q":"Keluarga Anda terpecah karena seorang anggota mulai mengkafirkan anggota lain yang tidak sepaham dengannya akibat doktrin ekstrem. Sikap Anda?", "opts":[{"t":"Menjadi penengah, mengajak dialog keluarga, dan mengarahkan anggota yang terpapar ke pembinaan tokoh agama moderat.","s":5},{"t":"Menjadi penengah dan mengajak dialog keluarga.","s":4},{"t":"Memihak salah satu kubu.","s":3},{"t":"Menjauhi konflik keluarga itu.","s":2},{"t":"Ikut mengkafirkan anggota keluarga lain.","s":1}], "ex":"Takfirisme memecah keluarga; solusinya dialog plus pembinaan tokoh moderat, bukan permusuhan atau pembiaran."},
{"id":"TKP-5164", "q":"Tetangga Anda mendidik anaknya dengan melarang total bergaul dengan anak berbeda keyakinan atas dasar paham intoleran. Sikap Anda sebagai tetangga?", "opts":[{"t":"Mencontohkan toleransi lewat interaksi wajar dan mengajak dialog bila ada kesempatan, tanpa menghakimi pola asuhnya.","s":5},{"t":"Tetap bersikap ramah dan mencontohkan toleransi.","s":4},{"t":"Menjauhi keluarga itu.","s":3},{"t":"Melaporkan pola asuhnya ke aparat.","s":2},{"t":"Ikut membatasi anak Anda bergaul dengannya.","s":1}], "ex":"Pola asuh intoleran paling efektif dilawan dengan keteladanan toleransi di lingkungan, bukan konfrontasi atau laporan yang belum berdasar pidana."},
{"id":"TKP-5165", "q":"Sebuah komunitas 'parenting Islami' yang Anda ikuti mulai mengajarkan orang tua untuk menanamkan kebencian intoleran ke anak sejak dini. Sikap Anda?", "opts":[{"t":"Keluar dari komunitas itu dan melaporkan materinya ke aparat bila bermuatan ekstrem.","s":5},{"t":"Keluar dari komunitas itu.","s":4},{"t":"Tetap ikut untuk materi parenting lainnya.","s":3},{"t":"Menerapkan ajarannya karena 'demi akidah anak'.","s":2},{"t":"Ikut menyebarkan materinya ke komunitas lain.","s":1}], "ex":"Parenting yang menanamkan kebencian adalah radikalisasi generasi berikutnya; wajib ditinggalkan dan dilaporkan."},
{"id":"TKP-5166", "q":"Anak Anda bertanya mengapa temannya dilarang orang tuanya bermain dengannya karena berbeda keyakinan, dengan nada intoleran dari orang tua temannya. Sikap Anda menjawab anak?", "opts":[{"t":"Menjelaskan dengan bahasa sederhana bahwa perbedaan keyakinan bukan alasan memusuhi, dan mencontohkan pertemanan yang baik.","s":5},{"t":"Menjelaskan bahwa setiap keluarga punya aturan sendiri.","s":4},{"t":"Menyuruh anak tidak usah memikirkannya.","s":3},{"t":"Melarang anak bermain dengan teman itu.","s":2},{"t":"Ikut memusuhi keluarga teman itu.","s":1}], "ex":"Anak yang bertanya soal intoleransi butuh penjelasan toleran yang sederhana; orang tua adalah madrasah pertama anti-ekstremisme."},
{"id":"TKP-5167", "q":"Seorang kerabat menawarkan 'pesantren kilat' untuk anak Anda selama liburan yang ternyata dikelola jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak dengan tegas dan melaporkan pesantren itu ke Kemenag serta aparat.","s":5},{"t":"Menolak dan mencari pesantren yang terverifikasi.","s":4},{"t":"Menerima karena gratis.","s":3},{"t":"Menerima karena kerabat yang menawarkan.","s":2},{"t":"Mendaftarkan plus mengajak keponakan lain.","s":1}], "ex":"Pesantren kilat jaringan ekstrem menarget anak saat liburan; wajib ditolak dan dilaporkan, pilih lembaga terverifikasi Kemenag."},
{"id":"TKP-5168", "q":"Di sekolah anak Anda, sekelompok siswa membentuk 'geng' yang mengintimidasi siswa berbeda keyakinan dengan dalih ekstrem. Sikap Anda sebagai orang tua murid?", "opts":[{"t":"Melaporkan ke sekolah dan meminta tindakan tegas, serta menguatkan anak agar tidak takut melapor.","s":5},{"t":"Melaporkan ke sekolah.","s":4},{"t":"Menasihati anak menghindar dari geng itu.","s":3},{"t":"Menyuruh anak melawan balik.","s":2},{"t":"Membiarkan karena 'kenakalan biasa'.","s":1}], "ex":"Intimidasi intoleran di sekolah bukan kenakalan biasa melainkan bibit ekstremisme yang wajib ditindak sekolah."},
{"id":"TKP-5169", "q":"Nenek di kampung Anda menjadi target 'kunjungan dakwah' rutin yang isinya doktrin kebencian yang intoleran dan ajakan menolak pemerintah. Sikap Anda sebagai cucunya?", "opts":[{"t":"Menemani nenek saat kunjungan, meluruskan dengan santun, dan melaporkan pendakwahnya bila bermuatan ekstrem.","s":5},{"t":"Melarang nenek menerima kunjungan itu.","s":4},{"t":"Membiarkan karena nenek senang ada yang mengunjungi.","s":3},{"t":"Ikut mendengarkan tanpa menegur.","s":2},{"t":"Memberi donasi ke pendakwahnya.","s":1}], "ex":"Lansia kesepian rentan doktrinasi; keluarga wajib mendampingi, meluruskan santun, dan melaporkan pendakwah ekstrem."},
{"id":"TKP-5170", "q":"Saudara Anda berencana menyekolahkan anaknya ke 'sekolah alam' yang kurikulumnya menolak Pancasila dan mengajarkan paham khilafah. Sikap Anda?", "opts":[{"t":"Menasihatinya memilih sekolah berizin resmi dan melaporkan sekolah itu ke dinas pendidikan.","s":5},{"t":"Menasihatinya memilih sekolah berizin resmi.","s":4},{"t":"Membiarkan karena hak orang tua.","s":3},{"t":"Mendukung karena konsepnya unik.","s":2},{"t":"Ikut menyekolahkan anak ke sana.","s":1}], "ex":"Sekolah tanpa izin yang menolak Pancasila adalah lembaga ilegal penanam ekstremisme; wajib dilaporkan ke dinas pendidikan."},
{"id":"TKP-5171", "q":"Anak Anda menonton konten 'eksperimen sosial' yang isinya pelecehan terhadap kelompok minoritas dengan dalih lucu-lucuan intoleran. Sikap Anda?", "opts":[{"t":"Melarang menonton, menjelaskan mengapa itu salah, dan melaporkan kontennya ke platform.","s":5},{"t":"Melarang menonton dan menjelaskan mengapa itu salah.","s":4},{"t":"Menertawakannya bersama anak.","s":3},{"t":"Membiarkan karena tren anak muda.","s":2},{"t":"Ikut membagikannya.","s":1}], "ex":"Konten pelecehan berkedok eksperimen sosial menormalisasi intoleransi pada anak; wajib dilarang dan dilaporkan."},
{"id":"TKP-5172", "q":"Sebuah biro umroh menawarkan 'paket hijrah' murah untuk remaja dengan itinerary yang mencakup 'pembekalan' bermuatan doktrin ekstrem. Sikap Anda sebagai orang tua yang ditawari?", "opts":[{"t":"Menolak paket itu dan melaporkan biro tersebut ke Kemenag serta aparat.","s":5},{"t":"Menolak dan memilih biro umroh resmi.","s":4},{"t":"Menerima karena murah.","s":3},{"t":"Menerima karena tetangga ikut juga.","s":2},{"t":"Mendaftarkan plus menjadi agen pemasarnya.","s":1}], "ex":"Paket hijrah bermuatan doktrin adalah rekrutmen berkedok ibadah; wajib ditolak dan dilaporkan, pilih biro resmi Kemenag."},
{"id":"TKP-5173", "q":"Di grup WA paguyuban orang tua murid, seorang anggota rutin menyebar ceramah provokatif bernada ekstrem. Sikap Anda?", "opts":[{"t":"Memprotes di grup, meminta admin menertibkan, dan melaporkan bila terus berlanjut.","s":5},{"t":"Memprotes dan meminta admin menertibkan.","s":4},{"t":"Mengabaikan pesannya.","s":3},{"t":"Keluar dari grup.","s":2},{"t":"Ikut menyebarkannya ke grup lain.","s":1}], "ex":"Grup orang tua murid bukan corong provokasi ekstrem; wajib diprotes, ditertibkan admin, dan dilaporkan bila membandel."},
{"id":"TKP-5174", "q":"Anak Anda diajak 'main perang-perangan' oleh tetangganya dengan skenario 'memerangi thaghut' yang ekstrem. Sikap Anda?", "opts":[{"t":"Melarang anak ikut permainan itu dan menegur orang tua tetangganya dengan baik.","s":5},{"t":"Melarang anak ikut permainan itu.","s":4},{"t":"Membiarkan karena hanya permainan anak.","s":3},{"t":"Ikut mengawasi sambil tertawa.","s":2},{"t":"Membelikan mainan senjata agar seru.","s":1}], "ex":"Permainan anak bernarasi ekstrem menanamkan kekerasan sejak dini; orang tua wajib melarang dan menegur dengan baik."},
{"id":"TKP-5175", "q":"Seorang famili jauh menawarkan mengasuh anak Anda sambil 'mendidik agama' yang ternyata berisi doktrin kebencian intoleran. Sikap Anda setelah mengetahuinya?", "opts":[{"t":"Mengambil alih pengasuhan anak, memutus pola didik itu, dan melaporkan bila doktrinnya bermuatan ekstrem.","s":5},{"t":"Mengambil alih pengasuhan anak dan memutus pola didik itu.","s":4},{"t":"Menasihati famili itu agar lebih lunak.","s":3},{"t":"Membiarkan karena tidak tega menolak famili.","s":2},{"t":"Menitipkan anak lebih lama agar 'tambah saleh'.","s":1}], "ex":"Pengasuhan berdoktrin kebencian meracuni anak; orang tua wajib mengambil alih dan memutusnya tanpa kompromi."}
,
{"id":"TKP-5176", "q":"Sebuah biro travel menawarkan 'wisata religi' ke luar negeri yang itinerary-nya mencakup kunjungan ke markas kelompok ekstrem. Sikap Anda sebagai calon peserta?", "opts":[{"t":"Menolak ikut dan melaporkan biro itu ke Kemenag serta aparat.","s":5},{"t":"Menolak ikut.","s":4},{"t":"Ikut tetapi menghindari kunjungan itu.","s":3},{"t":"Ikut karena paketnya murah.","s":2},{"t":"Ikut dan mengajak keluarga besar.","s":1}], "ex":"Wisata religi yang mengarahkan ke markas ekstrem adalah kedok rekrutmen; wajib ditolak dan dilaporkan."},
{"id":"TKP-5177", "q":"Di sela umroh yang Anda ikuti, seorang jamaah mengajak rombongan mampir ke 'majelis khusus' yang ternyata forum doktrinasi ekstrem. Sikap Anda?", "opts":[{"t":"Menolak ikut, memperingatkan jamaah lain, dan melaporkan ke pembimbing serta aparat setibanya di tanah air.","s":5},{"t":"Menolak ikut dan memperingatkan jamaah lain.","s":4},{"t":"Ikut sekali untuk melihat-lihat.","s":3},{"t":"Ikut karena sudah jauh-jauh ke sana.","s":2},{"t":"Ikut dan aktif berdiskusi di forum itu.","s":1}], "ex":"Ibadah umroh tidak boleh disusupi doktrinasi ekstrem; jamaah wajib menolak, memperingatkan, dan melaporkan."},
{"id":"TKP-5178", "q":"Seorang muthowwif menawarkan 'ziarah tambahan' berbayar ke lokasi yang dikenal sebagai basis propaganda teroris. Sikap Anda sebagai jamaah?", "opts":[{"t":"Menolak dan melaporkan muthowwif itu ke PPIH dan aparat.","s":5},{"t":"Menolak tawarannya.","s":4},{"t":"Ikut karena sudah membayar paket.","s":3},{"t":"Ikut karena penasaran.","s":2},{"t":"Ikut dan merekomendasikannya ke jamaah lain.","s":1}], "ex":"Ziarah tambahan ke basis propaganda teroris membahayakan jamaah; muthowwif-nya wajib dilaporkan ke PPIH."},
{"id":"TKP-5179", "q":"Kelompok ziarah wali yang Anda ikuti disusupi penceramah yang menyelipkan doktrin kebencian intoleran di setiap makam. Sikap Anda?", "opts":[{"t":"Menegur penceramah itu, mengajak peziarah lain menolak, dan melaporkan ke pengurus rombongan.","s":5},{"t":"Menegur penceramah itu agar kembali ke materi ziarah.","s":4},{"t":"Diam saja karena tidak enak dengan rombongan.","s":3},{"t":"Menyimak karena ceramahnya berapi-api.","s":2},{"t":"Merekam dan menyebarkannya.","s":1}], "ex":"Ziarah yang disusupi doktrin kebencian harus diluruskan di tempat dan dilaporkan; diam berarti membiarkan peziarah lain terpapar."},
{"id":"TKP-5180", "q":"Sebuah yayasan menggalang dana 'renovasi masjid' yang ternyata disalurkan untuk kegiatan kelompok ekstrem. Anda sudah berdonasi. Sikap Anda?", "opts":[{"t":"Menghentikan donasi lanjutan dan melaporkan yayasan itu ke aparat.","s":5},{"t":"Menghentikan donasi lanjutan.","s":4},{"t":"Tetap berdonasi karena niatnya ibadah.","s":3},{"t":"Menambah donasi agar pahala berlipat.","s":2},{"t":"Mengajak tetangga ikut berdonasi.","s":1}], "ex":"Donasi yang diselewengkan ke kelompok ekstrem wajib dihentikan dan dilaporkan; niat baik tidak membenarkan pendanaan ekstremisme."},
{"id":"TKP-5181", "q":"Tempat wisata religi di daerah Anda dijadikan ajang perekrutan 'relawan khilafah' oleh oknum pengelola. Sikap Anda sebagai warga setempat?", "opts":[{"t":"Melaporkan oknum itu ke pengelola wisata, pemda, dan aparat.","s":5},{"t":"Melaporkan ke pengelola wisata.","s":4},{"t":"Menghindari tempat itu.","s":3},{"t":"Membiarkan karena bukan urusan Anda.","s":2},{"t":"Ikut mendaftar sebagai relawan.","s":1}], "ex":"Pemanfaatan wisata religi untuk rekrutmen ekstrem merusak citra wisata dan wajib dilaporkan berjenjang."},
{"id":"TKP-5182", "q":"Seorang 'guide spiritual' di destinasi wisata menawarkan paket 'ruqyah massal' yang sesinya berisi doktrin anti-pemerintah yang ekstrem. Sikap Anda sebagai wisatawan?", "opts":[{"t":"Menolak ikut dan melaporkan guide itu ke pengelola destinasi serta aparat.","s":5},{"t":"Menolak ikut.","s":4},{"t":"Ikut karena sudah termasuk paket.","s":3},{"t":"Ikut karena ingin pengalaman spiritual.","s":2},{"t":"Ikut dan mengajak rombongan lain.","s":1}], "ex":"Ruqyah massal berdoktrin ekstrem adalah penipuan spiritual sekaligus propaganda yang wajib dilaporkan."},
{"id":"TKP-5183", "q":"Panitia peringatan hari besar keagamaan di kantor Anda mengundang penceramah yang dikenal menyebarkan paham intoleran. Sikap Anda sebagai pegawai?", "opts":[{"t":"Mengusulkan ke panitia agar penceramah diganti dan melaporkan bila ditolak.","s":5},{"t":"Mengusulkan ke panitia agar penceramah diganti.","s":4},{"t":"Tidak menghadiri acaranya.","s":3},{"t":"Menghadiri karena kewajiban kantor.","s":2},{"t":"Menghadiri dan memuji ceramahnya.","s":1}], "ex":"Acara keagamaan resmi tidak boleh diisi penceramah intoleran; pegawai wajib mengusulkan penggantian lewat mekanisme panitia."},
{"id":"TKP-5184", "q":"Sebuah festival budaya religi disponsori perusahaan yang mensyaratkan penampil menyisipkan pesan pro-khilafah. Sikap Anda sebagai panitia festival?", "opts":[{"t":"Menolak sponsor itu dan melaporkannya ke aparat.","s":5},{"t":"Menolak sponsor itu.","s":4},{"t":"Menerima sponsor tetapi mengabaikan syaratnya.","s":3},{"t":"Menerima dan memenuhi syaratnya.","s":2},{"t":"Menerima dan mempromosikan pesannya.","s":1}], "ex":"Sponsor bersyarat propaganda khilafah adalah pembelian panggung budaya; wajib ditolak dan dilaporkan."},
{"id":"TKP-5185", "q":"Rombongan wisata Anda diajak singgah ke 'pesantren' di luar negeri yang ternyata pusat indoktrinasi terorisme. Sikap Anda?", "opts":[{"t":"Menolak singgah, memperingatkan rombongan, dan melaporkan ke KBRI serta aparat.","s":5},{"t":"Menolak singgah dan memperingatkan rombongan.","s":4},{"t":"Ikut singgah karena itinerary resmi.","s":3},{"t":"Ikut karena penasaran dengan pesantren luar negeri.","s":2},{"t":"Ikut dan berfoto untuk media sosial.","s":1}], "ex":"Kunjungan ke pusat indoktrinasi terorisme membahayakan seluruh rombongan; wajib ditolak dan dilaporkan ke KBRI."},
{"id":"TKP-5186", "q":"Pengelola makam keramat di desa Anda memungut 'infak perjuangan' dari peziarah yang dananya disalurkan ke jaringan ekstrem. Sikap Anda sebagai perangkat desa?", "opts":[{"t":"Melarang pungutan itu dan melaporkan pengelolanya ke aparat.","s":5},{"t":"Melarang pungutan itu.","s":4},{"t":"Membiarkan karena sudah tradisi.","s":3},{"t":"Ikut berinfak agar berkah.","s":2},{"t":"Membantu mengelolanya.","s":1}], "ex":"Pungutan berkedok infak untuk jaringan ekstrem adalah pemerasan spiritual yang wajib dilarang dan dilaporkan."},
{"id":"TKP-5187", "q":"Sebuah aplikasi 'panduan ziarah digital' yang Anda unduh ternyata menyisipkan konten doktrinasi ekstrem di tiap destinasi. Sikap Anda?", "opts":[{"t":"Menghapus aplikasinya dan melaporkan ke platform serta aparat.","s":5},{"t":"Menghapus aplikasinya.","s":4},{"t":"Tetap memakai untuk navigasinya saja.","s":3},{"t":"Tetap memakai karena fiturnya lengkap.","s":2},{"t":"Merekomendasikannya ke teman.","s":1}], "ex":"Aplikasi ziarah berdoktrin ekstrem adalah radikalisasi digital berkedok ibadah yang wajib dilaporkan."},
{"id":"TKP-5188", "q":"Dalam perjalanan wisata religi, bus rombongan Anda diputar ceramah audio berisi hasutan intoleran oleh sopir. Sikap Anda sebagai peserta?", "opts":[{"t":"Meminta sopir mematikan, menegurnya, dan melaporkan ke biro travel.","s":5},{"t":"Meminta sopir mematikan ceramah itu.","s":4},{"t":"Memakai earphone sendiri.","s":3},{"t":"Mendengarkan karena tidak ada pilihan.","s":2},{"t":"Ikut menyimak dengan antusias.","s":1}], "ex":"Penumpang berhak atas perjalanan yang nyaman; hasutan intoleran di bus wisata wajib diprotes dan dilaporkan."},
{"id":"TKP-5189", "q":"Seorang tokoh agama lokal menjadikan pengajian rutinnya sebagai ajang penggalangan dana 'jihad' untuk kelompok ekstrem luar negeri. Sikap Anda sebagai jamaah?", "opts":[{"t":"Berhenti menghadiri pengajiannya dan melaporkan ke aparat.","s":5},{"t":"Berhenti menghadiri pengajiannya.","s":4},{"t":"Tetap hadir tetapi tidak menyumbang.","s":3},{"t":"Tetap hadir dan menyumbang.","s":2},{"t":"Menjadi koordinator penggalangannya.","s":1}], "ex":"Penggalangan dana jihad untuk kelompok ekstrem adalah pendanaan terorisme berkedok pengajian yang wajib dilaporkan."},
{"id":"TKP-5190", "q":"Desa wisata di daerah Anda dimasuki kelompok yang mengajak warga menolak wisatawan berbeda keyakinan dengan dalih intoleran. Sikap Anda sebagai pelaku wisata?", "opts":[{"t":"Menolak ajakan itu, mengedukasi warga tentang toleransi, dan melaporkan provokatornya.","s":5},{"t":"Menolak ajakan itu dan mengedukasi warga.","s":4},{"t":"Diam agar usaha tidak terganggu.","s":3},{"t":"Mengikuti ajakan demi 'keharmonisan warga'.","s":2},{"t":"Ikut mengusir wisatawan yang ditarget.","s":1}], "ex":"Penolakan wisatawan berbasis intoleransi merusak ekonomi desa dan citra bangsa; wajib dilawan dengan edukasi dan laporan."},
{"id":"TKP-5191", "q":"Sebuah majalah wisata religi memuat artikel yang mengagungkan 'destinasi perjuangan' kelompok teroris. Sikap Anda sebagai pembaca?", "opts":[{"t":"Melaporkan majalah itu ke Dewan Pers dan aparat.","s":5},{"t":"Berhenti membaca majalah itu.","s":4},{"t":"Menganggapnya rubrik sejarah biasa.","s":3},{"t":"Tertarik mengunjungi destinasi itu.","s":2},{"t":"Membagikan artikelnya sebagai referensi wisata.","s":1}], "ex":"Glorifikasi markas teroris sebagai destinasi wisata adalah propaganda yang wajib dilaporkan."},
{"id":"TKP-5192", "q":"Panitia qurban di masjid Anda dimasuki oknum yang menyelewengkan dana qurban untuk 'perjuangan' kelompok ekstrem. Sikap Anda sebagai jamaah?", "opts":[{"t":"Melaporkan oknum itu ke takmir dan aparat serta menuntut audit dana.","s":5},{"t":"Melaporkan ke takmir masjid.","s":4},{"t":"Pindah berqurban ke masjid lain.","s":3},{"t":"Tetap berqurban di sana karena sudah tradisi.","s":2},{"t":"Menambah hewan qurban tahun ini.","s":1}], "ex":"Penyelewengan dana qurban untuk ekstremisme adalah pengkhianatan amanah yang wajib dilaporkan dan diaudit."},
{"id":"TKP-5193", "q":"Sebuah komunitas 'hijrah traveler' mengajak anggotanya tur ke lokasi-lokasi bersejarah kelompok ekstrem dengan narasi kepahlawanan. Sikap Anda sebagai anggota?", "opts":[{"t":"Keluar dari komunitas itu dan melaporkan aktivitasnya ke aparat.","s":5},{"t":"Keluar dari komunitas itu.","s":4},{"t":"Ikut tur tetapi mengabaikan narasinya.","s":3},{"t":"Ikut tur karena destinasi bersejarah.","s":2},{"t":"Ikut dan mengagumi narasinya.","s":1}], "ex":"Tur napak tilas ekstremisme dengan narasi kepahlawanan adalah glorifikasi terorisme yang wajib dilaporkan."},
{"id":"TKP-5194", "q":"Pengajian akbar di kota Anda disusupi spanduk-spanduk dukungan untuk organisasi teroris. Sikap Anda sebagai peserta?", "opts":[{"t":"Melaporkan spanduk itu ke panitia dan aparat serta tidak terprovokasi.","s":5},{"t":"Melaporkan ke panitia.","s":4},{"t":"Mengabaikannya dan fokus pengajian.","s":3},{"t":"Berfoto dengan spanduknya.","s":2},{"t":"Ikut membentangkan spanduk serupa.","s":1}], "ex":"Spanduk dukungan teroris di pengajian akbar adalah provokasi yang wajib dilaporkan ke panitia dan aparat."},
{"id":"TKP-5195", "q":"Seorang agen travel umroh menawarkan diskon besar dengan syarat jamaah mengikuti 'pembekalan khusus' bermuatan doktrin khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan agen itu ke Kemenag serta aparat.","s":5},{"t":"Menolak dan memilih travel resmi.","s":4},{"t":"Menerima diskon tetapi menghindari pembekalannya.","s":3},{"t":"Menerima karena murah.","s":2},{"t":"Menerima dan mengajak tetangga.","s":1}], "ex":"Diskon umroh bersyarat doktrin khilafah adalah umpan rekrutmen; wajib ditolak dan dilaporkan, pilih travel resmi Kemenag."},
{"id":"TKP-5196", "q":"Di kawasan wisata religi, beredar buku saku 'doa-doa perjuangan' yang isinya doa kebencian intoleran terhadap kelompok lain. Sikap Anda sebagai pengunjung?", "opts":[{"t":"Tidak membeli dan melaporkan peredarannya ke pengelola serta aparat.","s":5},{"t":"Tidak membeli buku itu.","s":4},{"t":"Membeli sebagai oleh-oleh unik.","s":3},{"t":"Membeli karena doanya 'mustajab'.","s":2},{"t":"Memborong untuk dibagikan.","s":1}], "ex":"Buku doa kebencian adalah propaganda intoleran berkedok spiritualitas yang wajib dilaporkan peredarannya."},
{"id":"TKP-5197", "q":"Sebuah vlog travel religi yang Anda tonton mempromosikan 'kamp pelatihan' kelompok ekstrem sebagai destinasi menantang. Sikap Anda?", "opts":[{"t":"Melaporkan vlog itu ke platform dan aparat.","s":5},{"t":"Berhenti menonton vlog itu.","s":4},{"t":"Menonton sebagai hiburan.","s":3},{"t":"Tertarik mengunjunginya.","s":2},{"t":"Membagikannya ke teman petualang.","s":1}], "ex":"Promosi kamp pelatihan ekstrem sebagai destinasi wisata adalah glorifikasi terorisme yang wajib dilaporkan."},
{"id":"TKP-5198", "q":"Takmir masjid di kompleks Anda diajak kerja sama 'wisata dakwah' yang dananya dipakai membiayai propaganda khilafah. Sikap Anda sebagai jamaah?", "opts":[{"t":"Menolak kerja sama itu dalam rapat takmir dan melaporkan penyelenggaranya.","s":5},{"t":"Menolak kerja sama itu dalam rapat takmir.","s":4},{"t":"Abstain dalam voting.","s":3},{"t":"Setuju karena untuk dakwah.","s":2},{"t":"Mendukung dan menjadi panitianya.","s":1}], "ex":"Wisata dakwah berdana propaganda khilafah menyalahgunakan nama masjid; jamaah wajib menolak lewat forum takmir dan melapor."},
{"id":"TKP-5199", "q":"Dalam festival takbir keliling, sekelompok peserta meneriakkan yel-yel dukungan untuk kelompok teroris. Sikap Anda sebagai peserta lain?", "opts":[{"t":"Menegur mereka dan melaporkan ke panitia serta aparat.","s":5},{"t":"Menjauh dari kelompok itu.","s":4},{"t":"Mengabaikannya karena suasana meriah.","s":3},{"t":"Ikut meneriakkan agar kompak.","s":2},{"t":"Merekam dan menyebarkannya sebagai 'seru'.","s":1}], "ex":"Yel-yel dukungan teroris di festival keagamaan adalah provokasi ekstrem yang wajib ditegur dan dilaporkan."},
{"id":"TKP-5200", "q":"Sebuah agen perjalanan rohani menawarkan tur ke situs bersejarah yang ternyata menjadi tempat pembaiatan anggota baru kelompok ekstrem. Sikap Anda sebagai peserta tur?", "opts":[{"t":"Menolak ikut tur itu dan melaporkan agen tersebut ke Kemenag serta aparat.","s":5},{"t":"Menolak ikut tur itu.","s":4},{"t":"Ikut tur tetapi tidak ikut pembaiatannya.","s":3},{"t":"Ikut tur karena situsnya bersejarah.","s":2},{"t":"Ikut dan mengajak rombongan lain bergabung.","s":1}], "ex":"Tur rohani yang berujung pembaiatan ekstrem adalah jebakan rekrutmen; wajib ditolak dan dilaporkan."},
{"id":"TKP-5201", "q":"Kotak amal di kantor Anda dikelola oknum yang menyalurkan dana infak ke jaringan ekstrem. Sikap Anda sebagai pegawai?", "opts":[{"t":"Melaporkan oknum itu ke pimpinan dan aparat serta mengusulkan audit kotak amal.","s":5},{"t":"Melaporkan ke pimpinan kantor.","s":4},{"t":"Berhenti berinfak lewat kotak itu.","s":3},{"t":"Tetap berinfak karena niat ibadah.","s":2},{"t":"Menambah infak agar berkah.","s":1}], "ex":"Penyelewengan dana infak ke jaringan ekstrem adalah pengkhianatan amanah yang wajib dilaporkan dan diaudit."},
{"id":"TKP-5202", "q":"Sebuah lembaga amil zakat menawarkan Anda menjadi donatur tetap, tetapi laporan keuangannya buram dan terindikasi mengalir ke kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Menolak menjadi donatur dan melaporkan lembaga itu ke BAZNAS serta aparat.","s":5},{"t":"Menolak menjadi donatur.","s":4},{"t":"Tetap berzakat di sana karena dekat rumah.","s":3},{"t":"Menambah nominal zakatnya.","s":2},{"t":"Mengajak keluarga ikut berzakat di sana.","s":1}], "ex":"Lembaga amil yang buram dan terindikasi ekstrem wajib dilaporkan ke BAZNAS; zakat harus disalurkan lewat lembaga resmi dan transparan."},
{"id":"TKP-5203", "q":"Di bulan Ramadan, beredar proposal 'buka puasa bersama pejuang' yang dananya untuk kelompok bersenjata ekstrem. Sikap Anda sebagai penerima proposal?", "opts":[{"t":"Menolak dan melaporkan pengirimnya ke aparat.","s":5},{"t":"Menolak proposal itu.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Menyumbang sedikit karena kasihan.","s":2},{"t":"Menyumbang besar dan menyebarkan proposalnya.","s":1}], "ex":"Proposal berkedok buka puasa untuk kelompok bersenjata adalah pendanaan terorisme yang wajib dilaporkan."},
{"id":"TKP-5204", "q":"Teman Anda mengajak patungan 'sedekah subuh' via transfer ke rekening yang ternyata milik jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan rekening itu ke aparat.","s":5},{"t":"Menolak ikut.","s":4},{"t":"Ikut sekali karena diajak teman.","s":3},{"t":"Ikut rutin karena nominalnya kecil.","s":2},{"t":"Ikut dan mengajak teman lain.","s":1}], "ex":"Sedekah yang rekeningnya milik jaringan ekstrem adalah pendanaan terorisme; wajib ditolak dan dilaporkan."},
{"id":"TKP-5205", "q":"Sebuah masjid mengumumkan 'lelang amal' yang hasilnya disalurkan ke 'front perjuangan' kelompok ekstrem. Sikap Anda sebagai jamaah?", "opts":[{"t":"Memprotes di forum jamaah dan melaporkan ke aparat.","s":5},{"t":"Tidak mengikuti lelangnya.","s":4},{"t":"Mengikuti karena barangnya bagus.","s":3},{"t":"Ikut dan memenangkan lelangnya.","s":2},{"t":"Menyumbang barang untuk dilelang.","s":1}], "ex":"Lelang amal berdana front perjuangan ekstrem menyalahgunakan rumah ibadah; wajib diprotes dan dilaporkan."},
{"id":"TKP-5206", "q":"Aplikasi dompet digital menawarkan fitur 'sedekah otomatis' yang penyalurannya ke yayasan terindikasi ekstrem. Sikap Anda sebagai pengguna?", "opts":[{"t":"Menonaktifkan fitur itu dan melaporkan yayasannya ke aparat.","s":5},{"t":"Menonaktifkan fitur itu.","s":4},{"t":"Tetap aktif karena praktis.","s":3},{"t":"Menaikkan nominal sedekahnya.","s":2},{"t":"Merekomendasikan fitur itu ke teman.","s":1}], "ex":"Fitur sedekah otomatis ke yayasan ekstrem adalah pendanaan terorisme digital yang wajib dilaporkan."},
{"id":"TKP-5207", "q":"Panitia qurban menawarkan 'qurban patungan online' yang pengelolanya terindikasi jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak ikut dan melaporkan pengelolanya ke aparat.","s":5},{"t":"Menolak dan berqurban lewat lembaga resmi.","s":4},{"t":"Ikut karena murah.","s":3},{"t":"Ikut dan mengajak tetangga.","s":2},{"t":"Menjadi agen pemasarnya.","s":1}], "ex":"Qurban patungan berpengelola ekstrem menyelewengkan ibadah; wajib ditolak dan dilaporkan, pilih lembaga resmi."},
{"id":"TKP-5208", "q":"Seorang kolektor dana keliling membawa proposal 'pembangunan pesantren' yang ternyata fiktif dan dananya untuk propaganda ekstrem. Sikap Anda?", "opts":[{"t":"Menolak memberi dan melaporkan kolektor itu ke aparat.","s":5},{"t":"Menolak memberi.","s":4},{"t":"Memberi sedikit agar cepat pergi.","s":3},{"t":"Memberi karena kasihan.","s":2},{"t":"Memberi besar dan meminta proposal tambahan.","s":1}], "ex":"Proposal pesantren fiktif berdana propaganda ekstrem adalah penipuan sekaligus pendanaan terorisme yang wajib dilaporkan."},
{"id":"TKP-5209", "q":"Di kantor Anda, diedarkan 'kupon amal' yang hasilnya untuk 'korban konflik' tetapi pengelolanya jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak membeli dan melaporkan ke pimpinan serta aparat.","s":5},{"t":"Menolak membeli.","s":4},{"t":"Membeli satu karena sungkan.","s":3},{"t":"Membeli banyak untuk dibagikan.","s":2},{"t":"Membantu menjualkannya.","s":1}], "ex":"Kupon amal berkedok korban konflik untuk jaringan ekstrem wajib ditolak dan dilaporkan, bukan dibeli karena sungkan."},
{"id":"TKP-5210", "q":"Sebuah gala dinner amal menggalang dana 'pendidikan anak pejuang' yang ternyata anak-anak kombatan kelompok teroris. Sikap Anda sebagai undangan?", "opts":[{"t":"Menolak hadir dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menolak hadir.","s":4},{"t":"Hadir tetapi tidak menyumbang.","s":3},{"t":"Hadir dan menyumbang.","s":2},{"t":"Hadir dan menjadi donatur utama.","s":1}], "ex":"Gala dinner berdana anak kombatan teroris adalah pendanaan terorisme berkedok amal yang wajib dilaporkan."},
{"id":"TKP-5211", "q":"Teman Anda membuat grup 'sedekah Jumat' yang dananya rutin ditransfer ke 'guru' yang ternyata ideolog kelompok ekstrem. Sikap Anda sebagai anggota grup?", "opts":[{"t":"Keluar dari grup dan melaporkan penerima dananya ke aparat.","s":5},{"t":"Keluar dari grup.","s":4},{"t":"Tetap di grup tetapi tidak transfer.","s":3},{"t":"Tetap transfer karena sudah kebiasaan.","s":2},{"t":"Menaikkan nominal transfernya.","s":1}], "ex":"Sedekah rutin ke ideolog ekstrem adalah pembiayaan radikalisasi; wajib keluar dari grup dan melaporkan."},
{"id":"TKP-5212", "q":"Sebuah bazar amal di mal menjual merchandise yang keuntungannya untuk 'dakwah' kelompok intoleran. Sikap Anda sebagai pengunjung?", "opts":[{"t":"Tidak membeli dan melaporkan penyelenggaranya ke pengelola mal serta aparat.","s":5},{"t":"Tidak membeli.","s":4},{"t":"Membeli karena desainnya bagus.","s":3},{"t":"Membeli banyak sebagai oleh-oleh.","s":2},{"t":"Membantu mempromosikannya.","s":1}], "ex":"Bazar amal berdana dakwah intoleran wajib dihindari dan dilaporkan, bukan didukung karena desainnya."},
{"id":"TKP-5213", "q":"Pengurus RT mengusulkan iuran 'bantuan kemanusiaan' yang penyalurannya ke wilayah konflik lewat jaringan ekstrem. Sikap Anda sebagai warga?", "opts":[{"t":"Menolak usulan itu dalam rapat RT dan melaporkan ke RW serta aparat.","s":5},{"t":"Menolak usulan itu dalam rapat RT.","s":4},{"t":"Membayar karena tidak enak menolak.","s":3},{"t":"Membayar plus donasi tambahan.","s":2},{"t":"Menjadi koordinator pengumpulannya.","s":1}], "ex":"Iuran RT berpenyalur jaringan ekstrem wajib ditolak lewat forum resmi dan dilaporkan; membayar karena sungkan sama dengan mendanai."},
{"id":"TKP-5214", "q":"Seorang selebritas menggalang donasi 'peduli sesama muslim' yang auditnya menunjukkan aliran dana ke kelompok ekstrem. Anda sudah berdonasi. Sikap Anda?", "opts":[{"t":"Menghentikan donasi lanjutan, menuntut transparansi, dan melaporkan ke aparat.","s":5},{"t":"Menghentikan donasi lanjutan.","s":4},{"t":"Tetap berdonasi karena mengidolakannya.","s":3},{"t":"Menambah donasi sebagai dukungan.","s":2},{"t":"Membelanya dari kritik netizen.","s":1}], "ex":"Donasi selebritas yang mengalir ke ekstrem wajib dihentikan dan dilaporkan; kefanatikan tidak boleh mengalahkan akal sehat."},
{"id":"TKP-5215", "q":"Di tempat kerja, atasan mengimbau pegawai menyisihkan THR untuk 'panti asuhan' yang ternyata dikelola jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak imbauan itu dan melaporkan panti tersebut ke dinas sosial serta aparat.","s":5},{"t":"Menolak imbauan itu dengan halus.","s":4},{"t":"Menyisihkan sedikit karena imbauan atasan.","s":3},{"t":"Menyisihkan sesuai imbauan.","s":2},{"t":"Menyisihkan lebih sebagai contoh.","s":1}], "ex":"Imbauan atasan tidak boleh memaksa dana mengalir ke jaringan ekstrem; pegawai wajib menolak dan melaporkan."},
{"id":"TKP-5216", "q":"Sebuah platform crowdfunding menampung proyek 'sekolah gratis' yang kurikulumnya bermuatan doktrin terorisme. Sikap Anda sebagai donatur potensial?", "opts":[{"t":"Tidak berdonasi dan melaporkan proyek itu ke platform serta aparat.","s":5},{"t":"Tidak berdonasi.","s":4},{"t":"Berdonasi kecil karena untuk pendidikan.","s":3},{"t":"Berdonasi karena terharu videonya.","s":2},{"t":"Membagikan tautannya agar viral.","s":1}], "ex":"Crowdfunding sekolah berdoktrin terorisme adalah pembiayaan radikalisasi; wajib dilaporkan ke platform dan aparat."},
{"id":"TKP-5217", "q":"Kotak amal masjid di kampung Anda diganti pengelolanya dengan orang yang menyalurkan dana ke propaganda khilafah. Sikap Anda sebagai jamaah?", "opts":[{"t":"Memprotes dalam rapat takmir, menuntut audit, dan melaporkan ke aparat.","s":5},{"t":"Memprotes dalam rapat takmir.","s":4},{"t":"Berinfak ke masjid lain.","s":3},{"t":"Tetap berinfak karena niat ibadah.","s":2},{"t":"Menambah infak agar masjid makmur.","s":1}], "ex":"Pengambilalihan kotak amal untuk propaganda khilafah adalah pengkhianatan amanah jamaah yang wajib diprotes, diaudit, dan dilaporkan."},
{"id":"TKP-5218", "q":"Sebuah konser amal 'untuk kemanusiaan' ternyata headliner-nya adalah penceramah ekstrem dan dananya untuk jaringannya. Sikap Anda sebagai penonton yang sudah beli tiket?", "opts":[{"t":"Tidak menghadiri, meminta refund, dan melaporkan penyelenggaranya.","s":5},{"t":"Tidak menghadiri konsernya.","s":4},{"t":"Tetap hadir karena tiket mahal.","s":3},{"t":"Hadir dan menikmati konsernya.","s":2},{"t":"Hadir dan mengajak teman.","s":1}], "ex":"Konser amal berdana jaringan ekstrem wajib diboikot dan dilaporkan; harga tiket tidak sebanding dengan risiko mendanai ekstremisme."},
{"id":"TKP-5219", "q":"Teman Anda menitipkan 'dana titipan' ke Anda untuk diteruskan ke 'saudara seperjuangan' yang ternyata jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak meneruskan dan melaporkan teman itu ke aparat.","s":5},{"t":"Menolak meneruskan dana itu.","s":4},{"t":"Meneruskan karena hanya titipan.","s":3},{"t":"Meneruskan agar pertemanan baik.","s":2},{"t":"Meneruskan plus menambah dari kantong sendiri.","s":1}], "ex":"Meneruskan dana ke jaringan ekstrem — meski hanya titipan — adalah keterlibatan pendanaan terorisme yang wajib ditolak dan dilaporkan."},
{"id":"TKP-5220", "q":"Sebuah lelang barang sitaan 'untuk sosial' ternyata hasilnya disalurkan ke kelompok intoleran. Sikap Anda sebagai peserta lelang?", "opts":[{"t":"Menarik diri dan melaporkan penyelenggaranya ke aparat.","s":5},{"t":"Menarik diri dari lelang.","s":4},{"t":"Tetap ikut karena barangnya langka.","s":3},{"t":"Ikut dan memenangkan lelangnya.","s":2},{"t":"Ikut dan mempromosikannya.","s":1}], "ex":"Lelang sosial berdana kelompok intoleran wajib ditinggalkan dan dilaporkan."},
{"id":"TKP-5221", "q":"Penggalangan dana 'beasiswa santri' di media sosial ternyata untuk membiayai kaderisasi kelompok ekstrem. Sikap Anda yang hampir berdonasi?", "opts":[{"t":"Membatalkan donasi dan melaporkan akun itu ke platform serta aparat.","s":5},{"t":"Membatalkan donasi.","s":4},{"t":"Tetap berdonasi karena untuk santri.","s":3},{"t":"Berdonasi lebih agar berkah.","s":2},{"t":"Membagikan tautannya.","s":1}], "ex":"Beasiswa santri berkedok kaderisasi ekstrem adalah penipuan donasi yang wajib dilaporkan."},
{"id":"TKP-5222", "q":"Di arisan keluarga, seorang anggota mengusulkan kas arisan dipakai 'membantu perjuangan' kelompok bersenjata ekstrem. Sikap Anda?", "opts":[{"t":"Menolak keras dalam forum arisan dan melaporkan pengusulnya bila ia memaksa.","s":5},{"t":"Menolak dalam forum arisan.","s":4},{"t":"Diam agar arisan tidak bubar.","s":3},{"t":"Setuju karena untuk perjuangan.","s":2},{"t":"Mendukung dan menambah iuran.","s":1}], "ex":"Kas arisan bukan dana perjuangan bersenjata; usulan ekstrem wajib ditolak tegas dalam forum keluarga."},
{"id":"TKP-5223", "q":"Sebuah warung makan memasang kaleng 'donasi dakwah' yang dananya untuk propaganda intoleran. Sikap Anda sebagai pelanggan?", "opts":[{"t":"Tidak berdonasi dan melaporkan ke pemilik warung serta aparat bila perlu.","s":5},{"t":"Tidak berdonasi.","s":4},{"t":"Berdonasi receh karena kasihan.","s":3},{"t":"Berdonasi rutin.","s":2},{"t":"Membantu menyebarkan kaleng serupa.","s":1}], "ex":"Donasi dakwah berdana propaganda intoleran wajib dihindari dan dilaporkan."},
{"id":"TKP-5224", "q":"Sebuah turnamen olahraga amal yang Anda ikuti ternyata sponsor utamanya adalah perusahaan cangkang pendana kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Mengundurkan diri dan melaporkan temuan itu ke aparat.","s":5},{"t":"Mengundurkan diri dari turnamen.","s":4},{"t":"Tetap ikut karena sudah latihan.","s":3},{"t":"Tetap ikut dan memakai jersey sponsornya.","s":2},{"t":"Ikut dan mempromosikan sponsornya.","s":1}], "ex":"Turnamen amal bersponsor pendana ekstrem wajib ditinggalkan dan dilaporkan; prestasi tidak boleh dibiayai dana terorisme."},
{"id":"TKP-5225", "q":"Seorang donatur menawarkan membangun masjid di kampung Anda dengan syarat khotbahnya bermuatan doktrin khilafah. Sikap Anda sebagai tokoh masyarakat?", "opts":[{"t":"Menolak tawaran itu dan melaporkan donatur tersebut ke aparat.","s":5},{"t":"Menolak tawaran itu.","s":4},{"t":"Menerima tetapi mengabaikan syaratnya.","s":3},{"t":"Menerima karena kampung butuh masjid.","s":2},{"t":"Menerima dan memenuhi syaratnya.","s":1}], "ex":"Masjid bersyarat doktrin khilafah adalah infiltrasi ideologis; wajib ditolak meski kampung membutuhkan masjid."},
{"id":"TKP-5226", "q":"Seorang mantan narapidana terorisme yang telah bebas murni melamar menjadi guru ngaji di TPQ dekat rumah Anda. Sebagian wali murid menolak. Sikap Anda sebagai tokoh masyarakat?", "opts":[{"t":"Mendukung penerimaannya dengan syarat ia dalam pembinaan aparat dan materinya dimonitor takmir.","s":5},{"t":"Mendukung penerimaannya dan memberi kesempatan.","s":4},{"t":"Menolaknya demi ketenangan wali murid.","s":3},{"t":"Membiarkan wali murid memutuskan.","s":2},{"t":"Menyebarkan masa lalunya agar ia diusir.","s":1}], "ex":"Mantan narapidana terorisme yang terverifikasi bebas berhak reintegrasi dengan pembinaan; penolakan berbasis stigma menutup pintu tobat."},
{"id":"TKP-5227", "q":"Mantan narapidana terorisme di kampung Anda membuka usaha kuliner dan mempekerjakan warga. Sebagian warga memboikot usahanya karena masa lalunya. Sikap Anda?", "opts":[{"t":"Tetap menjadi pelanggannya dan mengajak warga lain bersikap adil selama ia berkelakuan baik.","s":5},{"t":"Tetap menjadi pelanggannya.","s":4},{"t":"Tidak peduli dengan usahanya.","s":3},{"t":"Ikut memboikot demi solidaritas warga.","s":2},{"t":"Menyebarkan isu bahwa usahanya kedok jaringan.","s":1}], "ex":"Boikot ekonomi terhadap mantan narapidana terorisme yang sudah tobat menghambat reintegrasi dan justru menyuburkan dendam."},
{"id":"TKP-5228", "q":"Seorang mantan narapidana terorisme ingin menjadi narasumber seminar deradikalisasi di kampus Anda untuk berbagi pengalaman tobat. Sikap Anda sebagai panitia?", "opts":[{"t":"Menerimanya dengan verifikasi status pembinaannya karena testimoni mantan pelaku sangat efektif untuk pencegahan.","s":5},{"t":"Menerimanya sebagai narasumber.","s":4},{"t":"Menolak karena khawatir citra kampus.","s":3},{"t":"Menerima tanpa verifikasi.","s":2},{"t":"Menolak dan menyebarkan penolakan ke media.","s":1}], "ex":"Testimoni mantan narapidana terorisme yang terverifikasi adalah senjata ampuh kontra-narasi; penolakan berbasis citra menyia-nyiakan potensinya."},
{"id":"TKP-5229", "q":"Anak mantan narapidana terorisme diejek 'anak teroris' oleh teman-temannya di sekolah hingga mogok sekolah. Sikap Anda sebagai guru kelasnya?", "opts":[{"t":"Menindak pelaku ejekan, memberi pendampingan ke anak itu, dan mengedukasi kelas tentang tidak menstigma.","s":5},{"t":"Menindak pelaku ejekan dan menenangkan anak itu.","s":4},{"t":"Menasihati anak itu agar sabar.","s":3},{"t":"Membiarkan karena kenakalan biasa.","s":2},{"t":"Menyarankan orang tuanya memindahkan sekolah.","s":1}], "ex":"Anak mantan narapidana terorisme adalah korban stigma yang butuh perlindungan sekolah; ejekan adalah perundungan yang wajib ditindak."},
{"id":"TKP-5230", "q":"Mantan narapidana terorisme yang sudah deradikalisasi ditawari menjadi penyuluh di lapas. Sebagian petugas lapas keberatan. Sikap Anda sebagai kalapas?", "opts":[{"t":"Tetap menugaskannya dengan pengawasan karena pengalamannya efektif membina narapidana terorisme lain.","s":5},{"t":"Tetap menugaskannya seperti penyuluh lain.","s":4},{"t":"Membatalkan penugasannya demi kenyamanan petugas.","s":3},{"t":"Menugaskannya tanpa pengawasan.","s":2},{"t":"Memutasinya ke tugas administratif saja.","s":1}], "ex":"Mantan narapidana terorisme terverifikasi adalah pembina paling kredibel bagi narapidana terorisme lain; keberatan petugas harus diatasi dengan pengawasan, bukan pembatalan."},
{"id":"TKP-5231", "q":"Warga menemukan mantan narapidana terorisme mengikuti pengajian rutin di masjid kampung dengan tertib. Sebagian jamaah ingin mengusirnya. Sikap Anda sebagai takmir?", "opts":[{"t":"Melindungi haknya beribadah dan mengajak jamaah menerima selama ia berkelakuan baik.","s":5},{"t":"Membiarkannya beribadah seperti jamaah lain.","s":4},{"t":"Memintanya pindah masjid.","s":3},{"t":"Ikut mengusirnya.","s":2},{"t":"Mengumumkan masa lalunya ke seluruh jamaah.","s":1}], "ex":"Masjid adalah rumah tobat; mengusir mantan narapidana terorisme yang berkelakuan baik bertentangan dengan semangat Islam dan menghambat reintegrasi."},
{"id":"TKP-5232", "q":"Seorang mantan narapidana terorisme melamar kerja di perusahaan Anda dengan kualifikasi terbaik, tetapi HRD ragu karena rekam jejaknya. Sikap Anda sebagai manajer?", "opts":[{"t":"Mendukung perekrutannya berdasarkan kompetensi dengan masa percobaan dan pembinaan yang jelas.","s":5},{"t":"Mendukung perekrutannya berdasarkan kompetensi.","s":4},{"t":"Menolaknya demi citra perusahaan.","s":3},{"t":"Menerimanya tetapi menyembunyikan dari karyawan lain.","s":2},{"t":"Menerimanya dengan gaji di bawah standar.","s":1}], "ex":"Rekrutmen berbasis kompetensi plus pembinaan adalah bentuk reintegrasi terbaik; diskriminasi rekam jejak melanggar prinsip keadilan."},
{"id":"TKP-5233", "q":"Mantan narapidana terorisme perempuan yang sudah bebas ingin aktif di PKK kampung Anda. Sebagian ibu-ibu menolak. Sikap Anda sebagai ketua PKK?", "opts":[{"t":"Menerimanya dan mengajak ibu-ibu lain memberi kesempatan dengan pembinaan yang wajar.","s":5},{"t":"Menerimanya seperti anggota baru lain.","s":4},{"t":"Menolaknya demi keharmonisan.","s":3},{"t":"Menerimanya tetapi mengucilkannya.","s":2},{"t":"Menyebarkan masa lalunya ke seluruh kampung.","s":1}], "ex":"Keterlibatan mantan narapidana terorisme dalam kegiatan sosial mempercepat reintegrasi; penolakan kolektif justru mengisolasi dan berbahaya."},
{"id":"TKP-5234", "q":"Seorang mantan narapidana terorisme menulis buku memoar tobatnya dan meminta Anda menulis kata pengantar sebagai tokoh masyarakat. Sikap Anda?", "opts":[{"t":"Bersedia setelah memverifikasi isi bukunya tidak mengandung glorifikasi dan mendukung pesan tobatnya.","s":5},{"t":"Bersedia menulis kata pengantar.","s":4},{"t":"Menolak karena tidak ingin dikaitkan.","s":3},{"t":"Bersedia tanpa membaca isinya.","s":2},{"t":"Menolak dan mengkritiknya di media.","s":1}], "ex":"Memoar tobat yang terverifikasi adalah kontra-narasi berharga; dukungan tokoh masyarakat memperkuat pesan deradikalisasi."},
{"id":"TKP-5235", "q":"Mantan narapidana terorisme di daerah Anda kembali menunjukkan gelagat mencurigakan: sering bertemu orang asing di malam hari. Sikap Anda sebagai tetangga?", "opts":[{"t":"Melaporkan kecurigaan itu ke aparat dengan fakta yang Anda amati, tanpa menuduh.","s":5},{"t":"Mengamati lebih lanjut sebelum bertindak.","s":4},{"t":"Mengabaikannya karena ia sudah bebas.","s":3},{"t":"Langsung menuduhnya kambuh di depan warga.","s":2},{"t":"Mengusirnya dari kampung.","s":1}], "ex":"Kecurigaan berbasis fakta wajib dilaporkan ke aparat tanpa prasangka; main hakim sendiri atau pembiaran sama-sama salah."},
{"id":"TKP-5236", "q":"Keluarga mantan narapidana terorisme kesulitan ekonomi dan meminta bantuan ke dinas sosial tempat Anda bekerja. Sikap Anda?", "opts":[{"t":"Memproses bantuannya sesuai prosedur dan merujuk ke program pemberdayaan agar mandiri.","s":5},{"t":"Memproses bantuannya sesuai prosedur.","s":4},{"t":"Menolak karena latar belakangnya.","s":3},{"t":"Mempersulit prosesnya.","s":2},{"t":"Memberi bantuan pribadi agar tidak tercatat.","s":1}], "ex":"Keluarga mantan narapidana terorisme berhak atas bantuan prosedural plus pemberdayaan; kesulitan ekonomi adalah faktor risiko radikalisasi ulang."},
{"id":"TKP-5237", "q":"Seorang mantan narapidana terorisme ingin mencalonkan diri sebagai ketua RT. Sebagian warga menolak karena masa lalunya. Sikap Anda sebagai warga?", "opts":[{"t":"Mendukung haknya mencalonkan dan menilai berdasarkan visi serta kelakuannya kini.","s":5},{"t":"Membiarkan proses demokrasi berjalan.","s":4},{"t":"Netral tetapi tidak memilihnya.","s":3},{"t":"Ikut menolak demi ketenangan.","s":2},{"t":"Berkampanye menjatuhkannya dengan isu masa lalu.","s":1}], "ex":"Hak politik mantan narapidana terorisme yang sudah bebas dilindungi; warga wajib menilainya dari kinerja kini, bukan stigma masa lalu."},
{"id":"TKP-5238", "q":"Mantan narapidana terorisme yang Anda kenal baik mengajak Anda kerja sama usaha dengan modal dari sumber yang tidak jelas. Sikap Anda?", "opts":[{"t":"Menolak kerja sama itu dan melaporkan bila sumber dananya mencurigakan.","s":5},{"t":"Menolak kerja sama itu dengan halus.","s":4},{"t":"Menerima karena mengenal baik orangnya.","s":3},{"t":"Menerima karena modalnya besar.","s":2},{"t":"Menerima dan mengajak investor lain.","s":1}], "ex":"Modal tak jelas dari mantan narapidana terorisme wajib dicurigai dan dilaporkan; kedekatan personal tidak boleh mengalahkan kewaspadaan."},
{"id":"TKP-5239", "q":"Dalam program desa, seorang mantan narapidana terorisme ditunjuk sebagai koordinator keamanan lingkungan. Sebagian warga protes. Sikap Anda sebagai kepala desa?", "opts":[{"t":"Tetap menugaskannya dengan pengawasan dan menjelaskan ke warga tentang pembinaannya.","s":5},{"t":"Tetap menugaskannya.","s":4},{"t":"Membatalkan penunjukannya.","s":3},{"t":"Menugaskannya tanpa penjelasan ke warga.","s":2},{"t":"Menggantinya diam-diam.","s":1}], "ex":"Pemberdayaan mantan narapidana terorisme dalam keamanan lingkungan adalah reintegrasi positif yang butuh transparansi ke warga plus pengawasan."},
{"id":"TKP-5240", "q":"Seorang mantan narapidana terorisme mengaku kepada Anda bahwa ia masih dihubungi jaringan lamanya dan diminta kembali aktif. Sikap Anda?", "opts":[{"t":"Mendorongnya melapor ke aparat dan mendampinginya, serta merahasiakan identitasnya.","s":5},{"t":"Mendorongnya melapor ke aparat.","s":4},{"t":"Menasihatinya menolak sendiri tanpa lapor.","s":3},{"t":"Merahasiakannya karena ia percaya pada Anda.","s":2},{"t":"Ikut menemuinya dengan jaringan itu.","s":1}], "ex":"Pengakuan mantan narapidana terorisme yang didekati jaringan lama adalah informasi intelijen berharga; wajib didorong melapor dengan perlindungan."},
{"id":"TKP-5241", "q":"Media lokal ingin mewawancarai mantan narapidana terorisme di kampung Anda untuk liputan 'kisah tobat'. Ia meminta pendapat Anda. Sikap Anda?", "opts":[{"t":"Mendukung dengan syarat liputannya tidak mengekspos identitas berlebihan dan pesannya edukatif.","s":5},{"t":"Mendukungnya.","s":4},{"t":"Menyarankan menolak wawancara.","s":3},{"t":"Mendukung tanpa syarat.","s":2},{"t":"Ikut diwawancara untuk popularitas.","s":1}], "ex":"Liputan kisah tobat bermanfaat bila menjaga keamanan narasumber dan pesannya edukatif, bukan sensasional."},
{"id":"TKP-5242", "q":"Anak mantan narapidana terorisme berprestasi dan diterima di sekolah favorit, tetapi pihak sekolah ragu menerimanya. Sikap Anda sebagai komite sekolah?", "opts":[{"t":"Mendukung penerimaannya berdasarkan prestasi dan memastikan ia tidak didiskriminasi.","s":5},{"t":"Mendukung penerimaannya.","s":4},{"t":"Menyerahkan ke kebijakan sekolah.","s":3},{"t":"Ikut meragukan.","s":2},{"t":"Mengusulkan penolakan halus.","s":1}], "ex":"Prestasi anak tidak boleh dikalahkan stigma orang tua; sekolah wajib inklusif dan anti-diskriminasi."},
{"id":"TKP-5243", "q":"Mantan narapidana terorisme yang sudah mapan menawarkan beasiswa untuk anak-anak kurang mampu di kampung Anda. Sebagian warga curiga. Sikap Anda?", "opts":[{"t":"Menerima beasiswanya dengan transparansi pengelolaan dan verifikasi sumber dananya.","s":5},{"t":"Menerima beasiswanya.","s":4},{"t":"Menolak karena curiga.","s":3},{"t":"Menerima tanpa verifikasi.","s":2},{"t":"Menolak dan menyebarkan kecurigaan.","s":1}], "ex":"Filantropi mantan narapidana terorisme patut diterima dengan transparansi dan verifikasi; kecurigaan tanpa bukti menghambat kebaikan."},
{"id":"TKP-5244", "q":"Dalam siskamling, mantan narapidana terorisme menjadi anggota paling rajin ronda. Sebagian warga tetap mencurigainya. Sikap Anda sebagai ketua RT?", "opts":[{"t":"Mengapresiasi kerajinannya dan mengajak warga menilai dari perilakunya kini.","s":5},{"t":"Membiarkannya ronda seperti warga lain.","s":4},{"t":"Mengeluarkannya dari jadwal ronda.","s":3},{"t":"Mengawasinya secara berlebihan.","s":2},{"t":"Melaporkannya tanpa bukti.","s":1}], "ex":"Partisipasi aktif mantan narapidana terorisme dalam siskamling adalah bukti reintegrasi yang patut diapresiasi, bukan dicurigai."},
{"id":"TKP-5245", "q":"Seorang mantan narapidana terorisme curhat kepada Anda bahwa ia kesulitan mendapat KTP karena ditolak aparat kelurahan. Sikap Anda?", "opts":[{"t":"Mendampinginya mengurus ke kelurahan dan memastikan hak administrasinya dipenuhi sesuai prosedur.","s":5},{"t":"Menasihatinya mengurus sesuai prosedur.","s":4},{"t":"Membiarkannya mengurus sendiri.","s":3},{"t":"Menyarankan memakai calo.","s":2},{"t":"Mengabaikannya.","s":1}], "ex":"Hak administrasi mantan narapidana terorisme dilindungi hukum; pendampingan memastikan tidak ada diskriminasi layanan."},
{"id":"TKP-5246", "q":"Mantan narapidana terorisme di komunitas Anda diminta menjadi imam salat Jumat menggantikan imam yang berhalangan. Sebagian jamaah keberatan. Sikap Anda sebagai takmir?", "opts":[{"t":"Tetap menugaskannya bila kompeten dan mengedukasi jamaah yang keberatan.","s":5},{"t":"Tetap menugaskannya.","s":4},{"t":"Membatalkannya demi ketenangan.","s":3},{"t":"Menugaskannya diam-diam.","s":2},{"t":"Mengumumkan penolakan di depan jamaah.","s":1}], "ex":"Kompetensi keagamaan mantan narapidana terorisme yang tobat tidak boleh dikalahkan stigma; takmir wajib mengedukasi jamaah."},
{"id":"TKP-5247", "q":"Seorang mantan narapidana terorisme membuka kanal YouTube berisi kontra-narasi ekstremisme dari sudut pandang mantan pelaku. Sikap Anda sebagai penonton?", "opts":[{"t":"Mendukung dengan menonton, membagikan, dan melaporkan bila ada pihak yang mengancamnya.","s":5},{"t":"Mendukung dengan menonton dan membagikan.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Mencurigainya sebagai kedok.","s":2},{"t":"Menyerangnya di kolom komentar.","s":1}], "ex":"Kontra-narasi oleh mantan pelaku adalah aset pencegahan yang layak didukung dan dilindungi dari ancaman."},
{"id":"TKP-5248", "q":"Keluarga Anda dijodohkan dengan keluarga mantan narapidana terorisme yang sudah tobat. Sebagian keluarga besar menolak. Sikap Anda?", "opts":[{"t":"Mendukung perjodohan berdasarkan kepribadian calon, bukan stigma keluarga.","s":5},{"t":"Menyerahkan ke kedua calon.","s":4},{"t":"Ikut menolak demi nama baik keluarga.","s":3},{"t":"Membatalkan sepihak.","s":2},{"t":"Menyebarkan isu masa lalunya.","s":1}], "ex":"Stigma keturunan tidak dikenal dalam hukum dan akhlak; perjodohan dinilai dari pribadi calon."},
{"id":"TKP-5249", "q":"Mantan narapidana terorisme yang menjadi tetangga Anda meminta surat keterangan domisili untuk melamar kerja. Sikap Anda sebagai ketua RT?", "opts":[{"t":"Menerbitkan surat itu sesuai prosedur seperti warga lain.","s":5},{"t":"Menerbitkan dengan verifikasi standar.","s":4},{"t":"Menolak menerbitkan.","s":3},{"t":"Mempersulit prosesnya.","s":2},{"t":"Menerbitkan dengan catatan 'eks narapidana terorisme'.","s":1}], "ex":"Pelayanan administrasi RT wajib setara untuk semua warga; stempel stigma di surat resmi adalah diskriminasi."},
{"id":"TKP-5250", "q":"Dalam musrenbang desa, seorang mantan narapidana terorisme mengusulkan program pencegahan radikalisme untuk pemuda. Sikap Anda sebagai peserta?", "opts":[{"t":"Mendukung usulannya dan mengusulkan dianggarkan karena ia paham dari dalam.","s":5},{"t":"Mendukung usulannya.","s":4},{"t":"Menolak karena pengusulnya.","s":3},{"t":"Mengabaikannya.","s":2},{"t":"Mencemooh usulannya di forum.","s":1}], "ex":"Usulan pencegahan dari mantan pelaku justru paling kredibel; forum desa wajib menilainya dari substansi."}
,
{"id":"TKP-5251", "q":"Guru agama di sekolah tempat anak Anda belajar ketahuan menyisipkan doktrin anti-Pancasila yang ekstrem dalam pelajarannya. Sikap Anda sebagai orang tua murid?", "opts":[{"t":"Melaporkan guru itu ke kepala sekolah dan dinas pendidikan agar ditindak tegas.","s":5},{"t":"Memprotes ke kepala sekolah.","s":4},{"t":"Menasihati anak agar tidak mengikuti ajarannya.","s":3},{"t":"Memindahkan anak ke sekolah lain tanpa protes.","s":2},{"t":"Membiarkan karena menghormati guru.","s":1}], "ex":"Guru penanam doktrin anti-Pancasila meracuni peserta didik; wajib dilaporkan ke dinas pendidikan."},
{"id":"TKP-5252", "q":"Sebuah sekolah swasta menawarkan kurikulum 'unggulan' yang ternyata mengajarkan penolakan ekstrem terhadap NKRI dan demokrasi. Sikap Anda sebagai orang tua calon siswa?", "opts":[{"t":"Menolak mendaftarkan anak dan melaporkan sekolah itu ke dinas pendidikan.","s":5},{"t":"Menolak mendaftarkan anak.","s":4},{"t":"Mendaftarkan karena fasilitasnya bagus.","s":3},{"t":"Mendaftarkan karena biayanya murah.","s":2},{"t":"Merekomendasikannya ke orang tua lain.","s":1}], "ex":"Sekolah berkurikulum anti-NKRI adalah lembaga radikalisasi berkedok pendidikan yang wajib dilaporkan."},
{"id":"TKP-5253", "q":"Dalam rapat komite sekolah, seorang anggota mengusulkan mengganti upacara bendera dengan 'kajian khilafah' karena dianggap lebih Islami. Sikap Anda?", "opts":[{"t":"Menolak usulan itu dengan tegas karena melanggar aturan pendidikan nasional.","s":5},{"t":"Menolak usulan itu.","s":4},{"t":"Abstain dalam voting.","s":3},{"t":"Setuju karena terdengar religius.","s":2},{"t":"Mendukung dan mengusulkan diperluas.","s":1}], "ex":"Upacara bendera adalah kewajiban pendidikan nasional; usulan menggantinya dengan kajian khilafah wajib ditolak tegas."},
{"id":"TKP-5254", "q":"Buku paket pelajaran di sekolah Anda memuat bab yang mengagungkan paham ekstrem sebagai 'perjuangan mulia'. Sikap Anda sebagai guru?", "opts":[{"t":"Melaporkan buku itu ke kepala sekolah dan dinas untuk ditarik dari peredaran.","s":5},{"t":"Tidak menggunakan bab itu dalam mengajar.","s":4},{"t":"Mengajarkan sesuai buku karena kewajiban.","s":3},{"t":"Mengajarkan dengan antusias.","s":2},{"t":"Merekomendasikan buku itu ke sekolah lain.","s":1}], "ex":"Buku pelajaran bermuatan ekstrem wajib dilaporkan dan ditarik; guru tidak boleh mengajarkannya."},
{"id":"TKP-5255", "q":"Seorang guru baru di sekolah Anda terang-terangan mengajak siswa bergabung ke kelompok kajian ekstrem sepulang sekolah. Sikap Anda sebagai rekan guru?", "opts":[{"t":"Melaporkan guru itu ke kepala sekolah dan aparat.","s":5},{"t":"Menegur guru itu agar berhenti.","s":4},{"t":"Membiarkan karena di luar jam sekolah.","s":3},{"t":"Menganggapnya kegiatan positif.","s":2},{"t":"Ikut mengajak siswa lain.","s":1}], "ex":"Guru perekrut kelompok ekstrem — meski di luar jam sekolah — membahayakan siswa dan wajib dilaporkan."},
{"id":"TKP-5256", "q":"Ekstrakurikuler rohis di sekolah Anda diambil alih alumni yang mengisinya dengan doktrin intoleran dan anti-Pancasila. Sikap Anda sebagai pembina?", "opts":[{"t":"Mengambil alih kembali pembinaan, mengganti pemateri, dan melaporkan alumni itu.","s":5},{"t":"Mengambil alih kembali pembinaan rohis.","s":4},{"t":"Membubarkan ekstrakurikuler itu.","s":3},{"t":"Membiarkan karena alumninya berpengaruh.","s":2},{"t":"Ikut menghadiri kajiannya.","s":1}], "ex":"Rohis yang dikuasai doktrin intoleran harus direbut kembali pembinanya; pembubaran justru menghilangkan wadah pembinaan positif."},
{"id":"TKP-5257", "q":"Dalam lomba cerdas cermat antar sekolah, soal-soal yang diberikan panitia menyudutkan Pancasila dan mengagungkan khilafah. Sikap Anda sebagai pendamping tim?", "opts":[{"t":"Memprotes ke panitia dan melaporkan ke dinas pendidikan.","s":5},{"t":"Memprotes ke panitia.","s":4},{"t":"Tetap mengikuti lomba demi siswa.","s":3},{"t":"Menganggapnya variasi soal.","s":2},{"t":"Mengapresiasi kreativitas panitia.","s":1}], "ex":"Lomba ber-soal propaganda khilafah meracuni ratusan siswa; wajib diprotes dan dilaporkan ke dinas."},
{"id":"TKP-5258", "q":"Seorang dosen di kampus Anda mewajibkan mahasiswanya membaca literatur ekstrem sebagai 'tugas kritis' tanpa pembanding. Sikap Anda sebagai kolega dosen?", "opts":[{"t":"Melaporkan ke jurusan karena tugas itu berpotensi meradikalisasi mahasiswa.","s":5},{"t":"Menegur kolega itu agar memberi literatur pembanding.","s":4},{"t":"Membiarkan karena otonomi akademik.","s":3},{"t":"Ikut memberi tugas serupa.","s":2},{"t":"Memuji inovasinya.","s":1}], "ex":"Tugas baca literatur ekstrem tanpa pembanding adalah indoktrinasi berkedok akademik yang wajib dilaporkan."},
{"id":"TKP-5259", "q":"OSIS sekolah Anda merencanakan bakti sosial yang ternyata dikoordinasikan dengan jaringan ekstrem sebagai ajang rekrutmen. Sikap Anda sebagai pembina OSIS?", "opts":[{"t":"Membatalkan kerja sama itu dan melaporkan jaringannya ke aparat.","s":5},{"t":"Membatalkan kerja sama itu.","s":4},{"t":"Tetap melaksanakan karena untuk sosial.","s":3},{"t":"Tetap melaksanakan dan mengajak siswa.","s":2},{"t":"Menjadikannya agenda rutin.","s":1}], "ex":"Bakti sosial berkedok rekrutmen ekstrem mengeksploitasi semangat sosial siswa; wajib dibatalkan dan dilaporkan."},
{"id":"TKP-5260", "q":"Wali kelas anak Anda mengirim pesan ke grup orang tua berisi ceramah provokatif bernada ekstrem. Sikap Anda?", "opts":[{"t":"Memprotes di grup dan melaporkan wali kelas itu ke kepala sekolah.","s":5},{"t":"Memprotes di grup orang tua.","s":4},{"t":"Mengabaikan pesannya.","s":3},{"t":"Keluar dari grup.","s":2},{"t":"Ikut menyebarkannya.","s":1}], "ex":"Wali kelas penyebar provokasi ekstrem menyalahgunakan posisinya; wajib diprotes dan dilaporkan."},
{"id":"TKP-5261", "q":"Sebuah bimbingan belajar menawarkan program 'karakter Islami' yang materinya menanamkan kebencian intoleran ke siswa. Sikap Anda sebagai orang tua yang ditawari?", "opts":[{"t":"Menolak dan melaporkan bimbel itu ke dinas pendidikan.","s":5},{"t":"Menolak mendaftarkan anak.","s":4},{"t":"Mendaftarkan karena butuh lesnya.","s":3},{"t":"Mendaftarkan karena murah.","s":2},{"t":"Merekomendasikannya.","s":1}], "ex":"Bimbel ber-materi kebencian intoleran meracuni siswa; wajib ditolak dan dilaporkan."},
{"id":"TKP-5262", "q":"Dalam ujian sekolah, soal buatan seorang guru menyisipkan doktrin bahwa 'demokrasi itu haram' yang ekstrem. Sikap Anda sebagai guru lain yang mengetahuinya?", "opts":[{"t":"Melaporkan guru itu ke kepala sekolah agar soalnya ditarik dan ditindak.","s":5},{"t":"Meminta soal itu direvisi.","s":4},{"t":"Membiarkan karena sudah terlanjur diujikan.","s":3},{"t":"Menganggapnya soal biasa.","s":2},{"t":"Ikut membuat soal serupa.","s":1}], "ex":"Soal ujian berdoktrin ekstrem adalah indoktrinasi massal yang wajib ditarik dan dilaporkan."},
{"id":"TKP-5263", "q":"Kantin sekolah tempat Anda mengajar dijadikan tempat 'kajian' oleh sekelompok siswa yang isinya propaganda khilafah. Sikap Anda?", "opts":[{"t":"Membubarkan kajian itu dan melaporkan ke kesiswaan serta memanggil orang tua siswa.","s":5},{"t":"Membubarkan kajian itu.","s":4},{"t":"Membiarkan karena di luar kelas.","s":3},{"t":"Ikut mendengarkan.","s":2},{"t":"Menyediakan konsumsi untuk kajiannya.","s":1}], "ex":"Kajian propaganda khilafah di kantin sekolah wajib dibubarkan dan dilaporkan; area sekolah tidak boleh jadi sarang radikalisasi."},
{"id":"TKP-5264", "q":"Seorang mahasiswa bimbingan Anda menulis skripsi yang kesimpulannya membenarkan aksi terorisme sebagai 'jihad sah'. Sikap Anda sebagai dosen pembimbing?", "opts":[{"t":"Menolak menyetujui skripsi itu dan melaporkannya ke jurusan.","s":5},{"t":"Meminta skripsinya direvisi total.","s":4},{"t":"Menyetujui dengan catatan.","s":3},{"t":"Menyetujui karena 'kebebasan akademik'.","s":2},{"t":"Memberi nilai tinggi karena berani.","s":1}], "ex":"Skripsi pembenar terorisme bukan kebebasan akademik melainkan propaganda; wajib ditolak dan dilaporkan."},
{"id":"TKP-5265", "q":"Perpustakaan sekolah menerima sumbangan buku-buku 'sejarah alternatif' yang isinya glorifikasi kelompok ekstrem. Sikap Anda sebagai pustakawan?", "opts":[{"t":"Menolak sumbangan itu dan melaporkannya ke kepala sekolah.","s":5},{"t":"Menolak sumbangan itu.","s":4},{"t":"Menerima tetapi tidak memajang.","s":3},{"t":"Menerima dan memajang.","s":2},{"t":"Menerima dan merekomendasikan ke siswa.","s":1}], "ex":"Sumbangan buku glorifikasi ekstrem adalah infiltrasi ke perpustakaan sekolah yang wajib ditolak dan dilaporkan."},
{"id":"TKP-5266", "q":"Dalam kegiatan pramuka, seorang pembina menyelipkan materi 'perang melawan thaghut' yang ekstrem. Sikap Anda sebagai pembina lain?", "opts":[{"t":"Menegur pembina itu dan melaporkan ke kwartir.","s":5},{"t":"Menegur pembina itu.","s":4},{"t":"Membiarkan karena variasi materi.","s":3},{"t":"Ikut menyampaikan materi serupa.","s":2},{"t":"Mengundangnya melatih di gugus lain.","s":1}], "ex":"Pramuka adalah pendidikan karakter Pancasila; materi perang thaghut wajib ditegur dan dilaporkan ke kwartir."},
{"id":"TKP-5267", "q":"Seorang guru honorer di sekolah Anda diketahui aktif sebagai admin kanal propaganda ekstrem. Sikap Anda sebagai kepala sekolah?", "opts":[{"t":"Memberhentikannya dan melaporkan ke dinas serta aparat.","s":5},{"t":"Memberhentikannya.","s":4},{"t":"Memberi peringatan tertulis.","s":3},{"t":"Membiarkan karena kekurangan guru.","s":2},{"t":"Mempertahankannya karena kinerjanya baik.","s":1}], "ex":"Guru admin propaganda ekstrem membahayakan seluruh siswa; wajib diberhentikan dan dilaporkan, tanpa toleransi."},
{"id":"TKP-5268", "q":"Komite sekolah mengusulkan dana BOS dipakai untuk 'pelatihan guru' yang penyelenggaranya terindikasi jaringan ekstrem. Sikap Anda sebagai kepala sekolah?", "opts":[{"t":"Menolak usulan itu dan melaporkan penyelenggaranya ke dinas serta aparat.","s":5},{"t":"Menolak usulan itu.","s":4},{"t":"Menyetujui karena untuk guru.","s":3},{"t":"Menyetujui dan ikut pelatihannya.","s":2},{"t":"Mengusulkan anggarannya ditambah.","s":1}], "ex":"Dana BOS tidak boleh mengalir ke jaringan ekstrem; usulan wajib ditolak dan dilaporkan."},
{"id":"TKP-5269", "q":"Siswa Anda bercerita bahwa di kampungnya ada 'sekolah' tanpa izin yang mengajarkan anak-anak membenci pemerintah dengan dalih ekstrem. Sikap Anda sebagai guru?", "opts":[{"t":"Melaporkan informasi itu ke dinas pendidikan dan aparat.","s":5},{"t":"Menggali informasi lebih lanjut dari siswa.","s":4},{"t":"Menasihati siswa agar tidak ikut.","s":3},{"t":"Mengabaikan cerita anak.","s":2},{"t":"Menganggapnya kabar burung.","s":1}], "ex":"Sekolah ilegal penanam kebencian adalah temuan penting yang wajib dilaporkan; guru adalah mata negara di lapangan."},
{"id":"TKP-5270", "q":"Dalam acara perpisahan sekolah, seorang alumni berpidato mengajak adik kelas 'berjuang menegakkan khilafah'. Sikap Anda sebagai guru pendamping?", "opts":[{"t":"Menghentikan pidatonya dengan santun dan melaporkan ke kepala sekolah.","s":5},{"t":"Menegurnya setelah acara.","s":4},{"t":"Membiarkan karena acara perpisahan.","s":3},{"t":"Bertepuk tangan.","s":2},{"t":"Mengundangnya lagi tahun depan.","s":1}], "ex":"Pidato ajakan khilafah di acara sekolah wajib dihentikan di tempat dan dilaporkan; momentum perpisahan bukan alasan pembiaran."},
{"id":"TKP-5271", "q":"Sebuah universitas luar negeri menawarkan beasiswa penuh ke dosen Anda dengan syarat penelitiannya 'mengkritik Pancasila' yang bermuatan ekstrem. Sikap Anda menasihati dosen itu?", "opts":[{"t":"Menasihatinya menolak dan melaporkan tawaran itu ke rektorat.","s":5},{"t":"Menasihatinya menolak.","s":4},{"t":"Mendukungnya karena beasiswa bergengsi.","s":3},{"t":"Ikut melamar beasiswa serupa.","s":2},{"t":"Membantu menyiapkan proposalnya.","s":1}], "ex":"Beasiswa bersyarat mengkritik Pancasila adalah intervensi ideologis asing; wajib ditolak dan dilaporkan."},
{"id":"TKP-5272", "q":"Grup belajar daring siswa Anda disusupi akun yang menyebarkan kuis-kuis berhadiah dengan konten doktrin ekstrem. Sikap Anda sebagai guru?", "opts":[{"t":"Melaporkan akun itu ke platform dan mengedukasi siswa agar waspada.","s":5},{"t":"Memperingatkan siswa agar tidak mengikuti kuisnya.","s":4},{"t":"Membiarkan karena di luar jam sekolah.","s":3},{"t":"Ikut kuisnya karena berhadiah.","s":2},{"t":"Membagikan kuisnya ke grup lain.","s":1}], "ex":"Kuis berhadiah berdoktrin ekstrem menarget siswa; guru wajib melaporkan dan mengedukasi literasi digital."},
{"id":"TKP-5273", "q":"Seorang orang tua murid memprotes kurikulum Pancasila di sekolah dengan dalih ekstrem dan mengancam akan memviralkan. Sikap Anda sebagai kepala sekolah?", "opts":[{"t":"Menegaskan kurikulum nasional wajib dilaksanakan dan melaporkannya bila disertai ancaman.","s":5},{"t":"Menegaskan kurikulum nasional wajib dilaksanakan.","s":4},{"t":"Memberi dispensasi khusus untuk anaknya.","s":3},{"t":"Mengurangi porsi Pancasila agar tidak ribut.","s":2},{"t":"Menghapus materi Pancasila dari sekolah.","s":1}], "ex":"Kurikulum nasional tidak bisa ditawar; protes ekstrem wajib dihadapi tegas dan ancaman dilaporkan."},
{"id":"TKP-5274", "q":"Dalam pelatihan guru yang Anda ikuti, pemateri menyelipkan ajakan menolak hormat bendera sebagai 'bukti keimanan' yang ekstrem. Sikap Anda?", "opts":[{"t":"Memprotes di forum dan melaporkan pemateri itu ke penyelenggara.","s":5},{"t":"Memprotes di forum pelatihan.","s":4},{"t":"Diam agar tidak ribut.","s":3},{"t":"Mengikuti ajakannya.","s":2},{"t":"Menyebarkan ajakannya ke guru lain.","s":1}], "ex":"Pelatihan guru bukan ajang doktrinasi anti-bendera; wajib diprotes di forum dan dilaporkan."},
{"id":"TKP-5275", "q":"Sekolah Anda mendapat tawaran 'laboratorium komputer gratis' dari donatur yang mensyaratkan instalasi aplikasi kajian ekstrem di semua PC. Sikap Anda?", "opts":[{"t":"Menolak tawaran itu dan melaporkan donatur tersebut.","s":5},{"t":"Menolak tawaran itu.","s":4},{"t":"Menerima tetapi tidak menginstal aplikasinya.","s":3},{"t":"Menerima dan menginstal sebagian.","s":2},{"t":"Menerima penuh dan mewajibkan siswa memakai.","s":1}], "ex":"Donasi bersyarat instalasi aplikasi ekstrem adalah infiltrasi digital ke sekolah; wajib ditolak dan dilaporkan."}
,
{"id":"TKP-5276", "q":"Anda melihat konten propaganda ekstrem viral di media sosial. Sebagai ASN yang peduli, sikap terbaik Anda?", "opts":[{"t":"Membuat kontra-narasi yang sejuk berbasis fakta dan melaporkan konten ekstrem itu ke platform serta aparat.","s":5},{"t":"Membuat kontra-narasi yang sejuk di akun Anda.","s":4},{"t":"Mengabaikannya karena bukan urusan Anda.","s":3},{"t":"Membagikannya agar orang waspada.","s":2},{"t":"Berdebat kasar dengan penyebarnya di kolom komentar.","s":1}], "ex":"Kontra-narasi efektif memadukan pesan sejuk berbasis fakta dengan pelaporan resmi; debat kasar justru memperkeruh."},
{"id":"TKP-5277", "q":"Teman Anda membagikan berita bohong bernada provokatif ekstrem tanpa verifikasi. Sikap Anda?", "opts":[{"t":"Menegurnya dengan baik, memberikan fakta pembanding, dan memintanya menghapus.","s":5},{"t":"Menegurnya dan memberikan fakta pembanding.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Ikut membagikan karena judulnya menarik.","s":2},{"t":"Menambah bumbu provokatif saat membagikan.","s":1}], "ex":"Hoaks provokatif ekstrem wajib dilawan dengan teguran baik plus fakta; ikut menyebar sama dengan menjadi corong propaganda."},
{"id":"TKP-5278", "q":"Di grup keluarga, beredar video ceramah yang memelintir ayat untuk membenarkan kekerasan ekstrem. Sikap Anda?", "opts":[{"t":"Meluruskan dengan penjelasan ulama moderat yang kredibel dan meminta pengirim tidak menyebar lagi.","s":5},{"t":"Meluruskan dengan penjelasan yang sejuk.","s":4},{"t":"Keluar dari grup.","s":3},{"t":"Meneruskannya ke grup lain untuk 'didiskusikan'.","s":2},{"t":"Membenarkan isi ceramahnya.","s":1}], "ex":"Pelintiran ayat untuk kekerasan wajib diluruskan dengan otoritas moderat; meneruskan untuk diskusi justru menyebarkan racun."},
{"id":"TKP-5279", "q":"Sekolah tempat Anda mengajar ingin mengadakan program literasi digital anti-hoaks dan anti-ekstremisme. Sikap Anda sebagai guru?", "opts":[{"t":"Mendukung penuh dan menawarkan diri menjadi koordinator program.","s":5},{"t":"Mendukung program itu.","s":4},{"t":"Netral dan tidak terlibat.","s":3},{"t":"Menolak karena menambah beban.","s":2},{"t":"Mengkritiknya sebagai program tidak penting.","s":1}], "ex":"Literasi digital adalah vaksin radikalisasi; guru wajib mendukung aktif program pencegahannya."},
{"id":"TKP-5280", "q":"Anda menemukan akun yang sistematis menyebarkan ujaran kebencian intoleran dengan ribuan pengikut. Sikap Anda?", "opts":[{"t":"Melaporkan akun itu ke platform dan aparat dengan bukti tangkapan layar.","s":5},{"t":"Melaporkan akun itu ke platform.","s":4},{"t":"Memblokirnya saja.","s":3},{"t":"Mengikutinya untuk memantau.","s":2},{"t":"Berdebat di setiap unggahannya.","s":1}], "ex":"Akun penyebar kebencian sistematis wajib dilaporkan dengan bukti; sekadar memblokir membiarkannya memangsa korban lain."},
{"id":"TKP-5281", "q":"Komunitas Anda ingin membuat kampanye 'Damai Itu Keren' untuk melawan narasi ekstrem di kalangan pemuda. Sikap Anda?", "opts":[{"t":"Terlibat aktif sebagai relawan dan mengajak pemuda lain bergabung.","s":5},{"t":"Mendukung kampanyenya.","s":4},{"t":"Tidak terlibat.","s":3},{"t":"Menganggapnya buang-buang waktu.","s":2},{"t":"Menyebarkan narasi tandingan yang ekstrem.","s":1}], "ex":"Kampanye damai butuh partisipasi aktif warga; apatisme membiarkan ruang publik dikuasai narasi ekstrem."},
{"id":"TKP-5282", "q":"Seorang teman yang mulai terpapar paham ekstrem masih mau diajak diskusi. Sikap Anda?", "opts":[{"t":"Mengajaknya dialog rutin dengan sabar, memberikan bacaan moderat, dan melibatkannya dalam kegiatan positif.","s":5},{"t":"Mengajaknya dialog dengan sabar.","s":4},{"t":"Menjauhinya agar tidak tertular.","s":3},{"t":"Memusuhinya sebagai 'sudah sesat'.","s":2},{"t":"Melaporkannya sebagai teroris tanpa bukti.","s":1}], "ex":"Orang yang masih mau dialog adalah peluang deradikalisasi; kesabaran plus kegiatan positif lebih efektif daripada pengucilan."},
{"id":"TKP-5283", "q":"Anda diundang menjadi narasumber webinar literasi digital untuk ibu-ibu PKK tentang bahaya hoaks ekstrem. Sikap Anda?", "opts":[{"t":"Bersedia dan menyiapkan materi yang mudah dipahami ibu-ibu.","s":5},{"t":"Bersedia menjadi narasumber.","s":4},{"t":"Menolak karena sibuk.","s":3},{"t":"Menolak karena bukan bidang Anda.","s":2},{"t":"Menyarankan materi yang provokatif agar seru.","s":1}], "ex":"Ibu-ibu adalah benteng keluarga dari hoaks; kesediaan berbagi literasi digital adalah kontribusi nyata pencegahan."},
{"id":"TKP-5284", "q":"Di tempat kerja, beredar surat kaleng berisi fitnah bernada SARA yang ekstrem terhadap seorang pegawai. Sikap Anda?", "opts":[{"t":"Melaporkan ke pimpinan dan mengajak rekan tidak terprovokasi fitnah itu.","s":5},{"t":"Melaporkan ke pimpinan.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Ikut mempercayai isinya.","s":2},{"t":"Ikut menyebarkannya.","s":1}], "ex":"Fitnah SARA di tempat kerja wajib dilaporkan dan dilawan dengan solidaritas; ikut menyebar merusak keharmonisan."},
{"id":"TKP-5285", "q":"Anak Anda bertanya tentang video propaganda ekstrem yang dilihatnya di internet. Sikap Anda sebagai orang tua?", "opts":[{"t":"Menjelaskan dengan bahasa sesuai usianya bahwa itu propaganda jahat dan mengajarkan cara memverifikasi informasi.","s":5},{"t":"Menjelaskan bahwa itu konten jahat.","s":4},{"t":"Melarang bertanya lebih jauh.","s":3},{"t":"Membiarkannya mencari tahu sendiri.","s":2},{"t":"Ikut menonton dan membenarkannya.","s":1}], "ex":"Rasa ingin tahu anak tentang propaganda wajib dijawab jujur plus dibekali literasi verifikasi, bukan dibungkam."},
{"id":"TKP-5286", "q":"Sebuah aplikasi pelaporan konten ekstrem diluncurkan pemerintah. Sikap Anda sebagai warga digital?", "opts":[{"t":"Mengunduhnya dan aktif melaporkan konten ekstrem yang Anda temui.","s":5},{"t":"Mengunduhnya.","s":4},{"t":"Tidak tertarik mengunduh.","s":3},{"t":"Menganggapnya alat mata-mata.","s":2},{"t":"Menyebarkan isu negatif tentang aplikasi itu.","s":1}], "ex":"Partisipasi warga dalam pelaporan adalah ujung tombak pemberantasan konten ekstrem; apatisme melemahkan upaya kolektif."},
{"id":"TKP-5287", "q":"Teman sekantor Anda menjadi korban doxing oleh kelompok intoleran karena menyuarakan toleransi. Sikap Anda?", "opts":[{"t":"Mendukungnya, membantunya melapor ke aparat, dan menggalang solidaritas rekan.","s":5},{"t":"Mendukungnya dan membantunya melapor.","s":4},{"t":"Menasihatinya diam agar aman.","s":3},{"t":"Menjauhinya agar tidak ikut disasar.","s":2},{"t":"Ikut menyalahkannya karena 'mencari masalah'.","s":1}], "ex":"Korban doxing intoleran butuh dukungan dan solidaritas; membiarkannya menang berarti membungkam suara toleransi."},
{"id":"TKP-5288", "q":"Di forum RT, seorang warga menyebarkan teori konspirasi bernada ekstrem tentang kelompok minoritas. Sikap Anda?", "opts":[{"t":"Meluruskan dengan fakta dan meminta admin forum menertibkan.","s":5},{"t":"Meluruskan dengan fakta.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Ikut mempercayainya.","s":2},{"t":"Ikut menyebarkannya ke forum lain.","s":1}], "ex":"Teori konspirasi ekstrem di forum warga wajib diluruskan dengan fakta; pembiaran menyuburkan prasangka kolektif."},
{"id":"TKP-5289", "q":"Anda memiliki keahlian desain dan diminta membuatkan infografis kontra-narasi melawan ekstremisme untuk kampanye damai. Sikap Anda?", "opts":[{"t":"Bersedia dengan senang hati dan memastikan pesannya akurat serta sejuk.","s":5},{"t":"Bersedia membantu.","s":4},{"t":"Menolak karena sibuk.","s":3},{"t":"Menolak karena tidak dibayar.","s":2},{"t":"Malah membuatkan desain untuk kubu ekstrem.","s":1}], "ex":"Keahlian untuk kontra-narasi adalah jihad damai di era digital; setiap profesi bisa berkontribusi."},
{"id":"TKP-5290", "q":"Seorang public figure yang Anda kagumi ternyata menyebarkan paham intoleran. Sikap Anda sebagai penggemar?", "opts":[{"t":"Berhenti mengidolakannya dan menyuarakan kekecewaan dengan cara yang beradab.","s":5},{"t":"Berhenti mengidolakannya.","s":4},{"t":"Tetap mengidolakan karyanya saja.","s":3},{"t":"Membelanya mati-matian.","s":2},{"t":"Ikut menyebarkan pahamnya.","s":1}], "ex":"Kekaguman tidak boleh membenarkan intoleransi; penggemar kritis berhenti mendukung dan bersuara beradab."},
{"id":"TKP-5291", "q":"Di kampus Anda akan diadakan festival keberagaman untuk melawan narasi intoleran. Sikap Anda sebagai mahasiswa?", "opts":[{"t":"Terlibat sebagai panitia dan mengajak teman-teman berpartisipasi.","s":5},{"t":"Menghadiri festivalnya.","s":4},{"t":"Tidak tertarik hadir.","s":3},{"t":"Menganggapnya acara tidak penting.","s":2},{"t":"Memprotes penyelenggaraannya.","s":1}], "ex":"Festival keberagaman adalah kontra-narasi nyata; partisipasi aktif memperkuat ketahanan kampus dari intoleransi."},
{"id":"TKP-5292", "q":"Teman Anda kecanduan grup-grup ekstrem di media sosial dan sulit diajak keluar. Sikap Anda?", "opts":[{"t":"Melibatkan keluarganya dan mengarahkan ke konseling serta melaporkan grupnya.","s":5},{"t":"Melibatkan keluarganya untuk membantunya.","s":4},{"t":"Membiarkannya karena pilihannya.","s":3},{"t":"Ikut bergabung agar bisa memantau.","s":2},{"t":"Menyerah dan memutus pertemanan.","s":1}], "ex":"Kecanduan grup ekstrem butuh intervensi keluarga dan konseling profesional; bukan dibiarkan atau dimusuhi."},
{"id":"TKP-5293", "q":"Sebuah survei menunjukkan meningkatnya intoleransi di kalangan pelajar daerah Anda. Sikap Anda sebagai pendidik?", "opts":[{"t":"Mengusulkan program pembinaan toleransi di sekolah dan melibatkannya dalam kurikulum.","s":5},{"t":"Membahasnya dalam rapat guru.","s":4},{"t":"Menganggapnya data biasa.","s":3},{"t":"Menyalahkan media sosial.","s":2},{"t":"Menganggap surveinya mengada-ada.","s":1}], "ex":"Data intoleransi pelajar adalah alarm yang wajib ditindaklanjuti dengan program pembinaan konkret, bukan didiamkan."},
{"id":"TKP-5294", "q":"Anda menemukan tutorial 'cara menghindari deteksi' yang disebar kelompok ekstrem di forum daring. Sikap Anda?", "opts":[{"t":"Melaporkan forum itu ke aparat siber dengan bukti lengkap.","s":5},{"t":"Melaporkan ke admin platform.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Mempelajarinya untuk wawasan.","s":2},{"t":"Membagikannya ke teman.","s":1}], "ex":"Tutorial anti-deteksi kelompok ekstrem adalah materi intelijen yang wajib dilaporkan ke aparat siber."},
{"id":"TKP-5295", "q":"Dalam diskusi keluarga besar, seorang kerabat menyampaikan pandangan intoleran yang ekstrem. Sikap Anda?", "opts":[{"t":"Menyanggah dengan lembut namun tegas dan memberikan perspektif toleran.","s":5},{"t":"Menyanggah pandangannya.","s":4},{"t":"Diam agar tidak ribut.","s":3},{"t":"Mengalihkan pembicaraan.","s":2},{"t":"Ikut membenarkannya.","s":1}], "ex":"Pandangan intoleran di keluarga wajib disanggah lembut-tegas; diam berarti memberi restu."},
{"id":"TKP-5296", "q":"Sebuah LSM mengajak Anda bergabung dalam program deradikalisasi sebagai relawan. Sikap Anda?", "opts":[{"t":"Bergabung dan berkontribusi sesuai kemampuan.","s":5},{"t":"Mendukung programnya.","s":4},{"t":"Tidak tertarik.","s":3},{"t":"Menolak karena takut.","s":2},{"t":"Menyebarkan isu negatif tentang LSM itu.","s":1}], "ex":"Relawan deradikalisasi adalah garda depan pencegahan; keterlibatan warga memperkuat program negara."},
{"id":"TKP-5297", "q":"Teman Anda membuat meme yang menertawakan korban aksi terorisme. Sikap Anda?", "opts":[{"t":"Menegurnya dengan keras bahwa itu tidak berempati dan memintanya menghapus.","s":5},{"t":"Menegurnya.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Tertawa bersamanya.","s":2},{"t":"Ikut menyebarkan meme itu.","s":1}], "ex":"Menertawakan korban terorisme adalah kebiadaban digital yang menormalisasi kekerasan; wajib ditegur dan dihapus."},
{"id":"TKP-5298", "q":"Di lingkungan kerja, Anda melihat rekan mulai menyukai dan membagikan konten-konten intoleran. Sikap pencegahan Anda?", "opts":[{"t":"Mengajaknya ngobrol empat mata, memberikan perspektif seimbang, dan melaporkan bila ia mulai menyebar di kantor.","s":5},{"t":"Mengajaknya ngobrol dan memberikan perspektif.","s":4},{"t":"Mengabaikannya.","s":3},{"t":"Menjauhinya.","s":2},{"t":"Ikut menyukai kontennya agar akrab.","s":1}], "ex":"Deteksi dini rekan terpapar butuh pendekatan personal; bila ia menyebar di kantor, wajib dilaporkan."},
{"id":"TKP-5299", "q":"Sebuah kompetisi menulis esai bertema 'Merawat Kebinekaan melawan intoleransi' diadakan di kota Anda. Sikap Anda?", "opts":[{"t":"Ikut serta dan mengajak orang lain berpartisipasi.","s":5},{"t":"Ikut serta.","s":4},{"t":"Tidak tertarik.","s":3},{"t":"Menganggapnya lomba seremonial.","s":2},{"t":"Menyebarkan isu bahwa lombanya settingan.","s":1}], "ex":"Kompetisi kebinekaan adalah ruang kontra-narasi yang layak diikuti dan disebarluaskan."},
{"id":"TKP-5300", "q":"Sebagai ASN, Anda diminta menjadi duta anti-radikalisme di instansi Anda. Sikap Anda?", "opts":[{"t":"Menerima dengan penuh tanggung jawab dan aktif mengedukasi rekan-rekan.","s":5},{"t":"Menerima tugas itu.","s":4},{"t":"Menolak dengan halus.","s":3},{"t":"Menerima tetapi pasif.","s":2},{"t":"Menolak dan menganggapnya pencitraan.","s":1}], "ex":"Duta anti-radikalisme adalah amanah pencegahan; ASN wajib menerimanya dengan tanggung jawab penuh."}]
